-- Component: database/functions/apply_event_payment_budget_semantics--12658278ea.sql
CREATE OR REPLACE FUNCTION public.apply_event_payment_budget_semantics()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_exempt boolean; v_type text;
BEGIN
 IF NEW.relation_type='payment' THEN
   SELECT living_budget_exempt INTO v_exempt FROM public.cash_flow_events WHERE id=NEW.cash_flow_event_id;
   SELECT transaction_type INTO v_type FROM public.transactions WHERE id=NEW.transaction_id;
   IF v_exempt AND v_type='expense' THEN UPDATE public.transactions SET budget_effect='excluded' WHERE id=NEW.transaction_id; END IF;
 END IF;
 RETURN NEW;
END $function$;

-- Component: database/functions/assert_free_cash_invariant--a2c2858b89.sql
CREATE OR REPLACE FUNCTION public.assert_free_cash_invariant(p_before numeric, p_after numeric, p_context text, p_tolerance numeric DEFAULT 0.01)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_before is not null and p_after is not null and abs(p_before-p_after)>p_tolerance then
    raise exception 'free_cash_until_next_income invariant failed for %: before %, after %, delta %',p_context,p_before,p_after,p_after-p_before;
  end if;
end
$function$;

-- Component: database/functions/business_day_on_or_before--cebbf35516.sql
CREATE OR REPLACE FUNCTION public.business_day_on_or_before(d date)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT CASE EXTRACT(ISODOW FROM d)::int WHEN 6 THEN d-1 WHEN 7 THEN d-2 ELSE d END $function$;

-- Component: database/functions/clear_credit_card_minimum_allocations--a521adf21e.sql
CREATE OR REPLACE FUNCTION public.clear_credit_card_minimum_allocations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN DELETE FROM public.cash_flow_event_funding WHERE transaction_id=OLD.id AND allocation_source='auto_card_minimum'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $function$;

-- Component: database/functions/clear_payment_buffer_funding_allocations--765bde8b76.sql
CREATE OR REPLACE FUNCTION public.clear_payment_buffer_funding_allocations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  delete from public.cash_flow_event_funding
  where transaction_id=old.id
    and allocation_source='auto_payment_buffer';

  if tg_op='DELETE' then
    return old;
  end if;
  return new;
end
$function$;

-- Component: database/functions/complete_income_event--935dedcc55.sql
CREATE OR REPLACE FUNCTION public.complete_income_event(p_event_id bigint, p_completed_at timestamp with time zone DEFAULT now())
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
 IF NOT EXISTS(SELECT 1 FROM public.cash_flow_events WHERE id=p_event_id AND event_type='income' AND status<>'cancelled') THEN RAISE EXCEPTION 'active income event % not found',p_event_id;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.transactions WHERE income_event_id=p_event_id AND occurred_at<=p_completed_at) THEN RAISE EXCEPTION 'income completion requires a receipt';END IF;
 UPDATE public.cash_flow_events SET income_completed_at=p_completed_at WHERE id=p_event_id;
 PERFORM public.refresh_cash_flow_event_status(p_event_id);
END $function$;

-- Component: database/functions/correct_finance_transaction--9009324eb2.sql
CREATE OR REPLACE FUNCTION public.correct_finance_transaction(p_transaction_id bigint, p_patch jsonb, p_category_allocations jsonb DEFAULT NULL::jsonb, p_debt_details jsonb DEFAULT NULL::jsonb, p_event_allocations jsonb DEFAULT NULL::jsonb, p_receipt_patch jsonb DEFAULT NULL::jsonb)
 RETURNS transactions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_old public.transactions;v_new public.transactions;x jsonb;k text;v_receipt public.receipts;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
 SELECT * INTO v_old FROM public.transactions WHERE id=p_transaction_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'transaction % not found',p_transaction_id;END IF;
 IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' THEN RAISE EXCEPTION 'patch must be a JSON object';END IF;
 FOR k IN SELECT jsonb_object_keys(p_patch) LOOP
  IF k NOT IN ('transaction_date','occurred_at','transaction_type','amount','description','category_id','from_account_id','to_account_id','liability_id','budget_effect','salary_component','salary_period_start','income_event_id','notes','reserve_effect','reserve_cycle','reserve_due_date','reserve_liability_id') THEN RAISE EXCEPTION 'unsupported transaction patch field %',k;END IF;
 END LOOP;
 -- Explicit replacements remove old dependent rows before validating the new ones.
 IF p_event_allocations IS NOT NULL THEN DELETE FROM public.cash_flow_event_funding WHERE transaction_id=p_transaction_id;END IF;
 IF p_debt_details IS NOT NULL THEN DELETE FROM public.debt_payment_details WHERE transaction_id=p_transaction_id;END IF;
 SELECT * INTO v_new FROM jsonb_populate_record(v_old,p_patch);
 UPDATE public.transactions SET transaction_date=v_new.transaction_date,occurred_at=v_new.occurred_at,transaction_type=v_new.transaction_type,amount=v_new.amount,description=v_new.description,category_id=v_new.category_id,from_account_id=v_new.from_account_id,to_account_id=v_new.to_account_id,liability_id=v_new.liability_id,budget_effect=v_new.budget_effect,salary_component=v_new.salary_component,salary_period_start=v_new.salary_period_start,income_event_id=v_new.income_event_id,notes=v_new.notes,reserve_effect=v_new.reserve_effect,reserve_cycle=v_new.reserve_cycle,reserve_due_date=v_new.reserve_due_date,reserve_liability_id=v_new.reserve_liability_id
 WHERE id=p_transaction_id;
 IF p_category_allocations IS NOT NULL THEN
  DELETE FROM public.transaction_category_allocations WHERE transaction_id=p_transaction_id;
  FOR x IN SELECT * FROM jsonb_array_elements(p_category_allocations) LOOP
   INSERT INTO public.transaction_category_allocations(transaction_id,category_id,amount,allocation_source) VALUES(p_transaction_id,(x->>'category_id')::bigint,(x->>'amount')::numeric,'manual');
  END LOOP;
 END IF;
 IF p_event_allocations IS NOT NULL THEN
  DELETE FROM public.cash_flow_event_funding WHERE transaction_id=p_transaction_id;
  FOR x IN SELECT * FROM jsonb_array_elements(p_event_allocations) LOOP
   INSERT INTO public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type,allocation_source) VALUES((x->>'event_id')::bigint,p_transaction_id,(x->>'amount')::numeric,x->>'relation_type','manual');
  END LOOP;
 END IF;
 IF p_debt_details IS NOT NULL AND p_debt_details<>'null'::jsonb THEN
  INSERT INTO public.debt_payment_details(transaction_id,liability_id,principal_amount,interest_amount,fee_amount,cash_flow_event_id)
  VALUES(p_transaction_id,v_new.liability_id,coalesce((p_debt_details->>'principal_amount')::numeric,0),coalesce((p_debt_details->>'interest_amount')::numeric,0),coalesce((p_debt_details->>'fee_amount')::numeric,0),(p_debt_details->>'event_id')::bigint);
 END IF;
 IF p_receipt_patch IS NOT NULL THEN
  FOR k IN SELECT jsonb_object_keys(p_receipt_patch) LOOP
   IF k NOT IN ('total_amount','purchase_at','merchant_name') THEN RAISE EXCEPTION 'unsupported receipt patch field %',k;END IF;
  END LOOP;
  SELECT * INTO v_receipt FROM public.receipts WHERE transaction_id=p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'no receipt linked to transaction %',p_transaction_id;END IF;
  SELECT * INTO v_receipt FROM jsonb_populate_record(v_receipt,p_receipt_patch);
  UPDATE public.receipts SET total_amount=v_receipt.total_amount,purchase_at=v_receipt.purchase_at,merchant_name=v_receipt.merchant_name WHERE transaction_id=p_transaction_id;
 END IF;
 SELECT * INTO v_new FROM public.transactions WHERE id=p_transaction_id;
 RETURN v_new;
END $function$;

-- Component: database/functions/execute_event--5dc04a140f.sql
CREATE OR REPLACE FUNCTION public.execute_event(p_event_id bigint, p_from_account_id bigint DEFAULT NULL::bigint, p_occurred_at timestamp with time zone DEFAULT now(), p_actual_amount numeric DEFAULT NULL::numeric, p_principal_amount numeric DEFAULT NULL::numeric, p_interest_amount numeric DEFAULT NULL::numeric, p_fee_amount numeric DEFAULT NULL::numeric)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e public.cash_flow_events;
  l public.liabilities;
  sch public.liability_payment_schedule;
  s record;
  v_amount numeric;
  v_from_id bigint;
  v_from_type text;
  v_tx_id bigint;
  v_category bigint;
  v_principal numeric;
  v_interest numeric;
  v_fee numeric;
  v_before numeric;
  v_after numeric;
  v_next_before date;
  v_next_after date; v_already numeric; v_available numeric;
begin
 perform pg_advisory_xact_lock(20260905,731);
  select * into e from public.cash_flow_events where id=p_event_id for update;
  if not found then raise exception 'cash flow event % not found',p_event_id; end if;
  if e.status='cancelled' then raise exception 'event % is % and cannot be executed again',p_event_id,e.status; end if;
  if e.event_type not in ('expense','debt_payment','planned_expense') then raise exception 'event % is not an executable outflow event',p_event_id; end if;

  select * into s from public.get_cash_flow_event_state_as_of(now()) where event_id=p_event_id;
  SELECT greatest(e.amount-coalesce(sum(amount),0),0) INTO v_available FROM public.cash_flow_event_funding WHERE cash_flow_event_id=e.id AND relation_type='payment';
  v_amount:=coalesce(p_actual_amount,v_available);
  if v_amount is null or v_amount<=0 then raise exception 'event % has no remaining payment',p_event_id; end if;
  if v_amount>v_available+0.005 then raise exception 'payment % exceeds remaining % for event %',v_amount,s.remaining_payment_amount,p_event_id; end if;

  select free_cash_until_next_income,next_income_date into v_before,v_next_before
  from public.get_liquidity_until_next_income(now(),null);

  if e.event_type='debt_payment' then
    if e.liability_id is null then raise exception 'debt payment event % has no liability',p_event_id; end if;
    select * into l from public.liabilities where id=e.liability_id;
    if l.balance_model='installment' then
      v_from_id:=coalesce(p_from_account_id,l.payment_account_id);
      if v_from_id is distinct from l.payment_account_id then
        raise exception 'installment event % must be debited from payment buffer %',p_event_id,l.payment_account_id;
      end if;
      if e.liability_payment_schedule_id is not null then
        select * into sch from public.liability_payment_schedule where id=e.liability_payment_schedule_id;
      end if;
      if p_principal_amount is null and p_interest_amount is null and p_fee_amount is null then
        if v_amount<>e.amount and e.liability_payment_schedule_id is not null then
          raise exception 'partial installment payment requires explicit principal/interest/fee decomposition';
        end if;
        if e.liability_payment_schedule_id is not null and sch.principal_amount is not null then
          v_principal:=sch.principal_amount; v_interest:=coalesce(sch.interest_amount,0); v_fee:=coalesce(sch.fee_amount,0);
        elsif l.annual_rate=0 then
          v_principal:=v_amount; v_interest:=0; v_fee:=0;
        else
          raise exception 'principal/interest decomposition is unknown for event %; provide it explicitly',p_event_id;
        end if;
      else
        v_principal:=coalesce(p_principal_amount,0);
        v_interest:=coalesce(p_interest_amount,0);
        v_fee:=coalesce(p_fee_amount,0);
      end if;
      if round(v_principal+v_interest+v_fee,2)<>round(v_amount,2) then
        raise exception 'principal + interest + fee must equal actual payment amount';
      end if;
      v_tx_id:=public.execute_installment_payment(p_event_id,p_occurred_at,v_amount,v_principal,v_interest,v_fee);
    elsif l.balance_model='revolving_account' then
      v_from_id:=p_from_account_id;
      if v_from_id is null then raise exception 'revolving payment requires p_from_account_id'; end if;
      select account_type into v_from_type from public.accounts where id=v_from_id and is_active;
      if v_from_type is null or v_from_type not in ('bank','cash') then raise exception 'revolving payment source must be bank/cash'; end if;
      select id into v_category from public.categories where category_type='debt' and is_active order by case when name='Погашение долга' then 0 else 1 end,id limit 1;
      insert into public.transactions(transaction_date,occurred_at,transaction_type,amount,currency,description,category_id,from_account_id,to_account_id,liability_id,budget_effect,notes)
      values(public.finance_business_date(p_occurred_at),p_occurred_at,'debt_payment',v_amount,'RUB',e.description,v_category,v_from_id,l.linked_account_id,l.id,'none','execute_event cash_flow_event_id='||p_event_id::text)
      returning id into v_tx_id;
      select coalesce(sum(amount),0) into v_already from public.cash_flow_event_funding where transaction_id=v_tx_id and cash_flow_event_id=p_event_id and relation_type='payment';
      if v_already<v_amount then
        insert into public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type,allocation_source)
        values(p_event_id,v_tx_id,v_amount-v_already,'payment','manual')
        on conflict(cash_flow_event_id,transaction_id) do update set amount=public.cash_flow_event_funding.amount+excluded.amount;
      end if;
    else
      raise exception 'unsupported liability model %',l.balance_model;
    end if;
  else
    v_from_id:=coalesce(p_from_account_id,e.account_id);
    if v_from_id is null then raise exception 'expense event % requires p_from_account_id',p_event_id; end if;
    select account_type into v_from_type from public.accounts where id=v_from_id and is_active;
    if v_from_type is null or v_from_type not in ('bank','cash','payment_buffer') then raise exception 'expense source account % has unsupported type %',v_from_id,v_from_type; end if;
    insert into public.transactions(transaction_date,occurred_at,transaction_type,amount,currency,description,category_id,from_account_id,to_account_id,liability_id,budget_effect,notes)
    values(public.finance_business_date(p_occurred_at),p_occurred_at,'expense',v_amount,'RUB',e.description,null,v_from_id,null,e.liability_id,case when e.living_budget_exempt then 'excluded' else 'life' end,'execute_event cash_flow_event_id='||p_event_id::text)
    returning id into v_tx_id;
    insert into public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type,allocation_source)
    values(p_event_id,v_tx_id,v_amount,'payment','manual');
  end if;

  select free_cash_until_next_income,next_income_date into v_after,v_next_after
  from public.get_liquidity_until_next_income(now(),null);
  if v_next_before is not null and v_next_before=v_next_after and e.event_date<v_next_before AND (e.event_type='debt_payment' OR e.living_budget_exempt) AND p_occurred_at<=now() then
    perform public.assert_free_cash_invariant(v_before,v_after,'execute_event '||p_event_id::text);
  end if;
  return v_tx_id;
end
$function$;

-- Component: database/functions/execute_installment_payment--84817fc831.sql
CREATE OR REPLACE FUNCTION public.execute_installment_payment(p_event_id bigint, p_occurred_at timestamp with time zone DEFAULT now(), p_actual_amount numeric DEFAULT NULL::numeric, p_principal_amount numeric DEFAULT NULL::numeric, p_interest_amount numeric DEFAULT NULL::numeric, p_fee_amount numeric DEFAULT NULL::numeric)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  e public.cash_flow_events;
  l public.liabilities;
  s public.liability_payment_schedule;
  v_amount numeric;
  v_principal numeric;
  v_interest numeric;
  v_fee numeric;
  v_balance numeric;
  v_tx_id bigint;
  v_category bigint; v_remaining numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
  SELECT * INTO e FROM public.cash_flow_events WHERE id=p_event_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cash flow event % not found',p_event_id; END IF;
  IF e.event_type<>'debt_payment' OR e.liability_id IS NULL THEN
    RAISE EXCEPTION 'event % is not an installment debt payment',p_event_id;
  END IF;
  SELECT * INTO l FROM public.liabilities WHERE id=e.liability_id;
  IF NOT FOUND OR l.balance_model<>'installment' OR l.payment_account_id IS NULL THEN
    RAISE EXCEPTION 'event % is not linked to an installment liability/payment account',p_event_id;
  END IF;
  IF e.liability_payment_schedule_id IS NOT NULL THEN
    SELECT * INTO s FROM public.liability_payment_schedule WHERE id=e.liability_payment_schedule_id;
  END IF;

  IF e.status='cancelled' THEN RAISE EXCEPTION 'cancelled event cannot be executed'; END IF;
  SELECT greatest(e.amount-coalesce(sum(amount),0),0) INTO v_remaining FROM public.cash_flow_event_funding WHERE cash_flow_event_id=e.id AND relation_type='payment';
  v_amount:=COALESCE(p_actual_amount,v_remaining);
  IF v_amount<=0 OR v_amount>v_remaining+0.005 THEN RAISE EXCEPTION 'payment exceeds remaining amount %',v_remaining; END IF;
  v_principal:=COALESCE(p_principal_amount,s.principal_amount);
  v_interest:=COALESCE(p_interest_amount,s.interest_amount,0);
  v_fee:=COALESCE(p_fee_amount,s.fee_amount,0);
  IF v_principal IS NULL THEN RAISE EXCEPTION 'principal decomposition is unknown for event %',p_event_id; END IF;
  IF round(v_principal+v_interest+v_fee,2)<>round(v_amount,2) THEN
    RAISE EXCEPTION 'decomposition does not equal actual payment amount';
  END IF;

  SELECT public.get_account_balance(l.payment_account_id,p_occurred_at) INTO v_balance;
  IF COALESCE(v_balance,0)<v_amount THEN
    RAISE EXCEPTION 'payment account % has %, but payment requires %',l.payment_account_id,COALESCE(v_balance,0),v_amount;
  END IF;

  SELECT id INTO v_category FROM public.categories
  WHERE category_type='debt' AND is_active
  ORDER BY CASE WHEN name='Погашение долга' THEN 0 ELSE 1 END,id LIMIT 1;

  INSERT INTO public.transactions(
    transaction_date,occurred_at,transaction_type,amount,currency,description,category_id,
    from_account_id,to_account_id,liability_id,budget_effect,notes
  ) VALUES(
    public.finance_business_date(p_occurred_at),p_occurred_at,'debt_payment',v_amount,'RUB',e.description,v_category,
    l.payment_account_id,NULL,l.id,'none','Executed installment payment for cash_flow_event_id='||e.id::text
  ) RETURNING id INTO v_tx_id;

  INSERT INTO public.debt_payment_details(
    transaction_id,liability_id,principal_amount,interest_amount,fee_amount,cash_flow_event_id
  ) VALUES(v_tx_id,l.id,v_principal,v_interest,v_fee,e.id);

  INSERT INTO public.cash_flow_event_funding(
    cash_flow_event_id,transaction_id,amount,relation_type,allocation_source
  ) VALUES(e.id,v_tx_id,v_amount,'payment','auto_installment');

  RETURN v_tx_id;
END
$function$;

-- Component: database/functions/finance_business_date--425398addf.sql
CREATE OR REPLACE FUNCTION public.finance_business_date(p_ts timestamp with time zone DEFAULT now())
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT (p_ts AT TIME ZONE public.finance_setting_text('business_timezone','Europe/Moscow'))::date $function$;

-- Component: database/functions/finance_command--4c19d2b97f.sql
CREATE OR REPLACE FUNCTION public.finance_command(p_request_key text, p_command text, p_args jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint;v_existing jsonb;v_payload jsonb;v_at timestamptz;v_tx public.transactions;d jsonb;a jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
 IF p_request_key IS NULL OR length(btrim(p_request_key))=0 THEN RAISE EXCEPTION 'request key is required';END IF;
 IF p_args IS NULL OR jsonb_typeof(p_args)<>'object' THEN RAISE EXCEPTION 'args must be a JSON object'; END IF;
 v_payload:=jsonb_build_object('command',p_command,'args',p_args);
 SELECT id,request_payload INTO v_id,v_existing FROM public.transactions WHERE external_ref=p_request_key FOR UPDATE;
 IF FOUND THEN
  IF v_existing IS DISTINCT FROM v_payload THEN RAISE EXCEPTION 'request key % already exists with different arguments',p_request_key;END IF;
  RETURN v_id;
 END IF;
 IF coalesce(p_args->>'reserve_effect','none')<>'none' AND p_command<>'record_transaction' THEN RAISE EXCEPTION 'tagged grace movements require record_transaction with optional event_allocations';END IF;
 v_at:=coalesce((p_args->>'occurred_at')::timestamptz,CASE WHEN p_args ? 'transaction_date' THEN public.finance_day_start((p_args->>'transaction_date')::date)+interval '12 hours' ELSE now() END);
 IF p_command='fund_event' THEN
  v_id:=public.fund_event((p_args->>'event_id')::bigint,(p_args->>'from_account_id')::bigint,(p_args->>'amount')::numeric,v_at,p_args->>'description');
 ELSIF p_command='execute_event' THEN
  v_id:=public.execute_event((p_args->>'event_id')::bigint,(p_args->>'from_account_id')::bigint,v_at,(p_args->>'amount')::numeric,(p_args->>'principal_amount')::numeric,(p_args->>'interest_amount')::numeric,(p_args->>'fee_amount')::numeric);
 ELSIF p_command='record_transaction' THEN
  INSERT INTO public.transactions(transaction_date,occurred_at,transaction_type,amount,currency,description,category_id,from_account_id,to_account_id,liability_id,budget_effect,salary_component,salary_period_start,income_event_id,notes,external_ref,request_payload)
  VALUES(coalesce((p_args->>'transaction_date')::date,public.finance_business_date(v_at)),v_at,p_args->>'transaction_type',(p_args->>'amount')::numeric,coalesce(p_args->>'currency','RUB'),p_args->>'description',(p_args->>'category_id')::bigint,(p_args->>'from_account_id')::bigint,(p_args->>'to_account_id')::bigint,(p_args->>'liability_id')::bigint,p_args->>'budget_effect',p_args->>'salary_component',(p_args->>'salary_period_start')::date,(p_args->>'income_event_id')::bigint,p_args->>'notes',p_request_key,v_payload)
  RETURNING id INTO v_id;
 ELSE RAISE EXCEPTION 'unsupported finance command %',p_command; END IF;
 IF p_args ? 'event_allocations' THEN
  IF p_command<>'record_transaction' THEN RAISE EXCEPTION 'event_allocations require record_transaction';END IF;
  FOR a IN SELECT * FROM jsonb_array_elements(p_args->'event_allocations') LOOP
   INSERT INTO public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type,allocation_source) VALUES((a->>'event_id')::bigint,v_id,(a->>'amount')::numeric,a->>'relation_type','manual');
  END LOOP;
 END IF;
 IF p_args ? 'category_allocations' THEN
  FOR a IN SELECT * FROM jsonb_array_elements(p_args->'category_allocations') LOOP
   INSERT INTO public.transaction_category_allocations(transaction_id,category_id,amount,allocation_source)
   VALUES(v_id,(a->>'category_id')::bigint,(a->>'amount')::numeric,'manual');
  END LOOP;
 END IF;
 IF p_args ? 'debt_details' THEN
  IF p_command<>'record_transaction' THEN RAISE EXCEPTION 'debt_details are accepted only for record_transaction';END IF;
  d:=p_args->'debt_details';
  INSERT INTO public.debt_payment_details(transaction_id,liability_id,principal_amount,interest_amount,fee_amount,cash_flow_event_id)
  VALUES(v_id,(p_args->>'liability_id')::bigint,coalesce((d->>'principal_amount')::numeric,0),coalesce((d->>'interest_amount')::numeric,0),coalesce((d->>'fee_amount')::numeric,0),(d->>'event_id')::bigint);
 END IF;
 UPDATE public.transactions SET external_ref=p_request_key,request_payload=v_payload,reserve_effect=coalesce(p_args->>'reserve_effect','none'),reserve_cycle=p_args->>'reserve_cycle',reserve_due_date=(p_args->>'reserve_due_date')::date,reserve_liability_id=(p_args->>'reserve_liability_id')::bigint WHERE id=v_id;
 RETURN v_id;
END $function$;

-- Component: database/functions/finance_data_issues--5926da9222.sql
CREATE OR REPLACE FUNCTION public.finance_data_issues()
 RETURNS TABLE(code text, entity_id bigint, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT 'transaction_date_mismatch',t.id,to_jsonb(t) FROM public.transactions t WHERE t.transaction_date<>public.finance_business_date(t.occurred_at)
 UNION ALL
 SELECT 'category_allocation_mismatch',t.id,jsonb_build_object('amount',t.amount,'allocated',a.total)
 FROM public.transactions t JOIN (SELECT transaction_id,sum(amount) total FROM public.transaction_category_allocations GROUP BY transaction_id)a ON a.transaction_id=t.id
 WHERE t.transaction_type<>'expense' OR round(t.amount,2)<>round(a.total,2)
 UNION ALL
 SELECT 'debt_detail_mismatch',t.id,jsonb_build_object('amount',t.amount,'detail_id',d.id)
 FROM public.transactions t JOIN public.debt_payment_details d ON d.transaction_id=t.id
 WHERE t.transaction_type<>'debt_payment' OR t.liability_id IS DISTINCT FROM d.liability_id OR round(t.amount,2)<>round(d.principal_amount+d.interest_amount+d.fee_amount,2)
 UNION ALL
 SELECT 'allocation_exceeds_transaction',t.id,jsonb_build_object('amount',t.amount,'allocated',a.total)
 FROM public.transactions t JOIN (SELECT transaction_id,sum(amount) total FROM public.cash_flow_event_funding GROUP BY transaction_id)a ON a.transaction_id=t.id WHERE a.total>t.amount+0.005
 UNION ALL
 SELECT 'allocation_exceeds_event',e.id,jsonb_build_object('amount',e.amount,'allocated',a.total,'relation',a.relation_type)
 FROM public.cash_flow_events e JOIN (SELECT cash_flow_event_id,relation_type,sum(amount) total FROM public.cash_flow_event_funding GROUP BY cash_flow_event_id,relation_type)a ON a.cash_flow_event_id=e.id WHERE a.total>e.amount+0.005
 UNION ALL
 SELECT 'cash_commitment_exceeds_event',e.id,jsonb_build_object('amount',e.amount,'allocated',a.total)
 FROM public.cash_flow_events e JOIN (SELECT f.cash_flow_event_id,sum(f.amount) total FROM public.cash_flow_event_funding f JOIN public.transactions t ON t.id=f.transaction_id JOIN public.accounts a ON a.id=t.from_account_id WHERE a.account_type IN ('bank','cash') GROUP BY f.cash_flow_event_id)a ON a.cash_flow_event_id=e.id WHERE a.total>e.amount+0.005
 UNION ALL
 SELECT 'allocation_semantics',f.id,jsonb_build_object('event',e.id,'transaction',t.id,'relation',f.relation_type)
 FROM public.cash_flow_event_funding f JOIN public.transactions t ON t.id=f.transaction_id JOIN public.cash_flow_events e ON e.id=f.cash_flow_event_id
 LEFT JOIN public.accounts fa ON fa.id=t.from_account_id LEFT JOIN public.accounts ta ON ta.id=t.to_account_id LEFT JOIN public.liabilities l ON l.id=e.liability_id
 WHERE (CASE WHEN f.relation_type='funding' THEN
   t.transaction_type='transfer' AND fa.account_type IN ('bank','cash') AND ta.account_type='payment_buffer' AND e.event_type IN ('expense','debt_payment','planned_expense')
   AND (e.liability_id IS NULL OR (l.balance_model='installment' AND t.to_account_id=l.payment_account_id))
   AND (e.liability_id IS NOT NULL OR e.account_id IS NULL OR t.to_account_id=e.account_id)
 ELSE
   CASE WHEN e.event_type='debt_payment' THEN t.transaction_type='debt_payment' AND t.liability_id=e.liability_id AND
    ((l.balance_model='installment' AND t.from_account_id=l.payment_account_id AND t.to_account_id IS NULL) OR (l.balance_model='revolving_account' AND fa.account_type IN ('bank','cash') AND t.to_account_id=l.linked_account_id))
   WHEN e.event_type IN ('expense','planned_expense') THEN t.transaction_type='expense' AND fa.account_type IN ('bank','cash','payment_buffer') AND t.to_account_id IS NULL AND (NOT e.living_budget_exempt OR t.budget_effect<>'life')
   ELSE false END END) IS NOT TRUE
 UNION ALL
 SELECT 'receipt_amount_mismatch',r.id,jsonb_build_object('receipt',r.total_amount,'transaction',t.amount) FROM public.receipts r JOIN public.transactions t ON t.id=r.transaction_id WHERE t.transaction_type<>'expense' OR round(r.total_amount,2)<>round(t.amount,2)
 UNION ALL
 SELECT 'receipt_items_mismatch',r.id,jsonb_build_object('receipt',r.total_amount,'items',coalesce(a.total,0)) FROM public.receipts r LEFT JOIN (SELECT receipt_id,sum(amount) total FROM public.receipt_items GROUP BY receipt_id)a ON a.receipt_id=r.id
 WHERE r.parse_status IN ('items_parsed','verified_online') AND round(r.total_amount,2)<>round(coalesce(a.total,0),2)
 UNION ALL
 SELECT 'income_link_mismatch',t.id,jsonb_build_object('event',t.income_event_id) FROM public.transactions t JOIN public.cash_flow_events e ON e.id=t.income_event_id WHERE t.transaction_type<>'income' OR e.event_type<>'income'
 UNION ALL
 SELECT 'liability_account_mismatch',l.id,jsonb_build_object('model',l.balance_model,'payment_account',l.payment_account_id,'linked_account',l.linked_account_id)
 FROM public.liabilities l LEFT JOIN public.accounts p ON p.id=l.payment_account_id LEFT JOIN public.accounts a ON a.id=l.linked_account_id
 WHERE (CASE WHEN l.balance_model='installment' THEN p.account_type='payment_buffer' ELSE a.account_type='credit_card' END) IS NOT TRUE
 UNION ALL
 SELECT 'detail_event_mismatch',d.id,jsonb_build_object('event',e.id,'liability',d.liability_id) FROM public.debt_payment_details d JOIN public.cash_flow_events e ON e.id=d.cash_flow_event_id WHERE e.event_type<>'debt_payment' OR e.liability_id IS DISTINCT FROM d.liability_id
 UNION ALL
 SELECT 'schedule_event_mismatch',e.id,jsonb_build_object('schedule',s.id) FROM public.cash_flow_events e JOIN public.liability_payment_schedule s ON s.id=e.liability_payment_schedule_id WHERE e.liability_id IS DISTINCT FROM s.liability_id OR e.event_type<>'debt_payment'
 UNION ALL
 SELECT 'movement_time_mismatch',m.id,jsonb_build_object('transaction',t.id) FROM public.liability_movements m JOIN public.transactions t ON t.id=m.transaction_id WHERE m.debt_payment_detail_id IS NOT NULL AND m.effective_at<>t.occurred_at;
$function$;

