-- Component: database/functions/finance_validate_data_deferred--9903e2cc8c.sql
CREATE OR REPLACE FUNCTION public.finance_validate_data_deferred()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
 SELECT * INTO r FROM public.finance_data_issues() LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'finance integrity: %, entity %, details %',r.code,r.entity_id,r.details USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$;

-- Component: database/functions/finance_write_lock--493e7475cb.sql
CREATE OR REPLACE FUNCTION public.finance_write_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF current_setting('transaction_isolation')='repeatable read' THEN RAISE EXCEPTION 'Finance writes require READ COMMITTED or SERIALIZABLE'; END IF;
 PERFORM pg_advisory_xact_lock(20260905,731);
 RETURN NULL;
END $function$;

-- Component: database/functions/forecast_free_cash--888649f7ff.sql
CREATE OR REPLACE FUNCTION public.forecast_free_cash(p_target_date date, p_weekly_living numeric DEFAULT 20000, p_reserve numeric DEFAULT 0)
 RETURNS TABLE(current_free_cash numeric, planned_income numeric, secured_outflows numeric, unsecure_outflows numeric, remaining_living_budget numeric, living_budget_overrun numeric, future_living_budget numeric, projected_free_cash numeric, safe_extra_payment numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 WITH t AS (SELECT * FROM public.get_financial_position_v2(p_target_date,p_weekly_living)),n AS (SELECT * FROM public.get_financial_position_v2(public.finance_business_date(now()),p_weekly_living)) SELECT n.free_cash,t.expected_income,t.secured_future_outflows,t.required_cash_flow_outflows,t.remaining_living_budget,GREATEST(t.current_week_spend-t.current_week_budget,0),t.future_living_budget,t.free_cash,GREATEST(t.free_cash-p_reserve,0) FROM t,n
$function$;

-- Component: database/functions/fund_event--e24cde05db.sql
CREATE OR REPLACE FUNCTION public.fund_event(p_event_id bigint, p_from_account_id bigint, p_amount numeric DEFAULT NULL::numeric, p_occurred_at timestamp with time zone DEFAULT now(), p_description text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e public.cash_flow_events;
  l public.liabilities;
  s record;
  v_from_type text;
  v_to_account_id bigint;
  v_to_type text;
  v_amount numeric;
  v_balance numeric;
  v_tx_id bigint;
  v_before numeric;
  v_after numeric;
  v_next_before date;
  v_next_after date;
begin
 perform pg_advisory_xact_lock(20260905,731);
  select * into e from public.cash_flow_events where id=p_event_id for update;
  if not found then raise exception 'cash flow event % not found',p_event_id; end if;
  if e.status in ('executed','cancelled') then raise exception 'event % is % and cannot be funded',p_event_id,e.status; end if;
  if e.event_type not in ('expense','debt_payment','planned_expense') then raise exception 'event % is not an outflow event',p_event_id; end if;

  select * into s from public.get_cash_flow_event_state_as_of(now()) where event_id=p_event_id;
  v_amount:=coalesce(p_amount,s.cash_still_required);
  if v_amount is null or v_amount<=0 then raise exception 'event % does not require funding',p_event_id; end if;
  if v_amount>s.cash_still_required+0.005 then raise exception 'funding % exceeds cash still required % for event %',v_amount,s.cash_still_required,p_event_id; end if;

  select account_type into v_from_type from public.accounts where id=p_from_account_id and is_active;
  if v_from_type is null or v_from_type not in ('bank','cash') then raise exception 'fund_event source % must be an active bank/cash account',p_from_account_id; end if;

  if e.liability_id is not null then
    select * into l from public.liabilities where id=e.liability_id;
    v_to_account_id:=l.payment_account_id;
  else
    v_to_account_id:=e.account_id;
  end if;
  if v_to_account_id is null then raise exception 'event % has no payment buffer; execute it directly instead of funding',p_event_id; end if;
  select account_type into v_to_type from public.accounts where id=v_to_account_id and is_active;
  if v_to_type is distinct from 'payment_buffer' then raise exception 'event % target account % is %, not payment_buffer',p_event_id,v_to_account_id,v_to_type; end if;

  select public.get_account_balance(p_from_account_id,p_occurred_at) into v_balance;
  if coalesce(v_balance,0)+0.005<v_amount then raise exception 'source account % has %, funding requires %',p_from_account_id,coalesce(v_balance,0),v_amount; end if;

  select free_cash_until_next_income,next_income_date into v_before,v_next_before
  from public.get_liquidity_until_next_income(now(),null);

  insert into public.transactions(transaction_date,occurred_at,transaction_type,amount,currency,description,category_id,from_account_id,to_account_id,liability_id,budget_effect,notes)
  values(public.finance_business_date(p_occurred_at),p_occurred_at,'transfer',v_amount,'RUB',coalesce(p_description,'Обеспечение: '||e.description),null,p_from_account_id,v_to_account_id,null,'none','fund_event cash_flow_event_id='||p_event_id::text)
  returning id into v_tx_id;

  insert into public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type,allocation_source)
  values(p_event_id,v_tx_id,v_amount,'funding','manual');

  select free_cash_until_next_income,next_income_date into v_after,v_next_after
  from public.get_liquidity_until_next_income(now(),null);
  if v_next_before is not null and v_next_before=v_next_after and e.event_date<v_next_before AND (e.event_type='debt_payment' OR e.living_budget_exempt) AND p_occurred_at<=now() then
    perform public.assert_free_cash_invariant(v_before,v_after,'fund_event '||p_event_id::text);
  end if;
  return v_tx_id;
end
$function$;

-- Component: database/functions/generate_cash_flow_events--5188dc9aeb.sql
CREATE OR REPLACE FUNCTION public.generate_cash_flow_events(from_date date, to_date date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r record; period date; d date; amt numeric; monthly_salary numeric; adv numeric; vacation numeric; adv_rule bigint; skey text;v_seen text[]:=ARRAY[]::text[];v_obsolete record;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
  IF to_date<from_date THEN RAISE EXCEPTION 'to_date must be >= from_date'; END IF;
  monthly_salary:=public.finance_setting_numeric('monthly_salary',NULL);
  IF monthly_salary IS NULL AND EXISTS (
    SELECT 1 FROM public.cash_flow_rules WHERE is_active
      AND rule_type IN ('salary_advance','salary_balance')
  ) THEN
    RAISE EXCEPTION 'monthly_salary must be configured before generating salary events';
  END IF;
  SELECT id INTO adv_rule FROM public.cash_flow_rules WHERE rule_type='salary_advance' AND is_active ORDER BY id LIMIT 1;

  FOR r IN SELECT * FROM public.cash_flow_rules WHERE is_active ORDER BY CASE rule_type WHEN 'salary_advance' THEN 1 WHEN 'salary_balance' THEN 2 ELSE 0 END,id LOOP
    IF r.schedule_type='weekly' THEN
      IF r.payment_day IS NULL OR r.payment_day<1 OR r.payment_day>7 THEN
        RAISE EXCEPTION 'weekly rule % requires payment_day 1..7 (ISO weekday)',r.id;
      END IF;
      d:=from_date + ((r.payment_day-EXTRACT(ISODOW FROM from_date)::int+7)%7);
      WHILE d<=to_date LOOP
        IF (r.start_date IS NULL OR d>=r.start_date) AND (r.end_date IS NULL OR d<=r.end_date) THEN
          amt:=r.amount;
          skey:='rule:'||r.id::text||':'||d::text;v_seen:=array_append(v_seen,skey);
          INSERT INTO public.cash_flow_events(
            event_date,event_type,amount,description,account_id,liability_id,is_planned,is_secured,rule_id,period_start,period_end,
            calculation_method,living_budget_exempt,status,source_type,source_key,fulfillment_mode
          ) VALUES(
            d,r.event_type,amt,r.name,r.account_id,r.liability_id,true,false,r.id,d,d,
            r.calculation_method,r.living_budget_exempt,'planned','rule',skey,'dated_payment'
          )
          ON CONFLICT(source_key) WHERE source_key IS NOT NULL DO UPDATE SET
            event_date=EXCLUDED.event_date,event_type=EXCLUDED.event_type,
            amount=CASE WHEN public.cash_flow_events.status IN ('planned','partially_secured','secured') THEN EXCLUDED.amount ELSE public.cash_flow_events.amount END,
            description=EXCLUDED.description,account_id=coalesce(EXCLUDED.account_id,public.cash_flow_events.account_id),liability_id=EXCLUDED.liability_id,rule_id=EXCLUDED.rule_id,
            period_start=EXCLUDED.period_start,period_end=EXCLUDED.period_end,calculation_method=EXCLUDED.calculation_method,
            living_budget_exempt=EXCLUDED.living_budget_exempt,source_type='rule',fulfillment_mode='dated_payment' WHERE public.cash_flow_events.status NOT IN ('executed','partially_executed','cancelled');
        END IF;
        d:=d+7;
      END LOOP;
      CONTINUE;
    END IF;

    period:=date_trunc('month',from_date-interval '1 month')::date;
    WHILE period<=date_trunc('month',to_date)::date LOOP
      IF r.rule_type='salary_balance' THEN
        d:=make_date(EXTRACT(YEAR FROM period+interval '1 month')::int,EXTRACT(MONTH FROM period+interval '1 month')::int,
          LEAST(COALESCE(r.payment_day,5),EXTRACT(DAY FROM (date_trunc('month',period+interval '1 month')+interval '1 month - 1 day'))::int));
      ELSE
        d:=make_date(EXTRACT(YEAR FROM period)::int,EXTRACT(MONTH FROM period)::int,
          LEAST(COALESCE(r.payment_day,1),EXTRACT(DAY FROM (date_trunc('month',period)+interval '1 month - 1 day'))::int));
      END IF;
      IF r.weekend_rule='previous_business_day' THEN d:=public.business_day_on_or_before(d); END IF;

      IF d BETWEEN from_date AND to_date AND (r.start_date IS NULL OR d>=r.start_date)
         AND (r.end_date IS NULL OR d<=r.end_date) THEN
        IF r.rule_type='salary_advance' THEN
          amt:=ROUND(monthly_salary*COALESCE(r.share_of_monthly_salary,0.5),2);
        ELSIF r.rule_type='salary_balance' THEN
          SELECT COALESCE(SUM(t.amount),0) INTO adv FROM public.transactions t
          WHERE t.transaction_type='income' AND t.salary_component='advance' AND t.salary_period_start=period;
          IF adv=0 THEN
            SELECT COALESCE(MAX(CASE WHEN e.status='executed' AND e.actual_amount IS NOT NULL THEN e.actual_amount ELSE e.amount END),0)
            INTO adv FROM public.cash_flow_events e WHERE e.rule_id=adv_rule AND e.period_start=period AND e.status<>'cancelled';
          END IF;
          IF adv=0 THEN adv:=ROUND(monthly_salary*0.5,2); END IF;
          SELECT COALESCE(SUM(t.amount),0) INTO vacation FROM public.transactions t
          WHERE t.transaction_type='income' AND t.salary_component='vacation' AND t.salary_period_start=period;
          amt:=GREATEST(monthly_salary-adv-vacation,0);
        ELSE
          amt:=r.amount;
        END IF;

        skey:='rule:'||r.id::text||':'||period::text;v_seen:=array_append(v_seen,skey);
        INSERT INTO public.cash_flow_events(
          event_date,event_type,amount,description,account_id,liability_id,is_planned,is_secured,rule_id,period_start,period_end,
          calculation_method,living_budget_exempt,status,source_type,source_key,fulfillment_mode
        ) VALUES(
          d,r.event_type,amt,r.name,r.account_id,r.liability_id,true,false,r.id,period,(period+interval '1 month - 1 day')::date,
          r.calculation_method,r.living_budget_exempt,'planned','rule',skey,'dated_payment'
        )
        ON CONFLICT(source_key) WHERE source_key IS NOT NULL DO UPDATE SET
          event_date=EXCLUDED.event_date,event_type=EXCLUDED.event_type,
          amount=CASE WHEN public.cash_flow_events.status IN ('planned','partially_secured','secured') THEN EXCLUDED.amount ELSE public.cash_flow_events.amount END,
          description=EXCLUDED.description,account_id=coalesce(EXCLUDED.account_id,public.cash_flow_events.account_id),liability_id=EXCLUDED.liability_id,rule_id=EXCLUDED.rule_id,
          period_start=EXCLUDED.period_start,period_end=EXCLUDED.period_end,calculation_method=EXCLUDED.calculation_method,
          living_budget_exempt=EXCLUDED.living_budget_exempt,source_type='rule',fulfillment_mode='dated_payment' WHERE public.cash_flow_events.status NOT IN ('executed','partially_executed','cancelled');
      END IF;
      period:=(period+interval '1 month')::date;
    END LOOP;
  END LOOP;

  FOR r IN
    SELECT s.*,l.name liability_name,l.payment_account_id
    FROM public.liability_payment_schedule s JOIN public.liabilities l ON l.id=s.liability_id
    WHERE l.status='active' AND l.balance_model='installment' AND s.payment_date BETWEEN from_date AND to_date AND s.total_amount>0
    ORDER BY s.payment_date,s.id
  LOOP
    skey:='bank_schedule:'||r.liability_id::text||':'||r.payment_date::text;v_seen:=array_append(v_seen,skey);
    INSERT INTO public.cash_flow_events(
      event_date,event_type,amount,description,account_id,liability_id,is_planned,is_secured,period_start,period_end,calculation_method,
      living_budget_exempt,status,source_type,source_key,fulfillment_mode,liability_payment_schedule_id
    ) VALUES(
      r.payment_date,'debt_payment',r.total_amount,r.liability_name,r.payment_account_id,r.liability_id,true,false,r.payment_date,r.payment_date,
      'bank_schedule',true,'planned','bank_schedule',skey,'dated_payment',r.id
    )
    ON CONFLICT(source_key) WHERE source_key IS NOT NULL DO UPDATE SET
      event_date=EXCLUDED.event_date,
      amount=CASE WHEN public.cash_flow_events.status IN ('planned','partially_secured','secured') THEN EXCLUDED.amount ELSE public.cash_flow_events.amount END,
      description=EXCLUDED.description,account_id=coalesce(EXCLUDED.account_id,public.cash_flow_events.account_id),liability_id=EXCLUDED.liability_id,
      period_start=EXCLUDED.period_start,period_end=EXCLUDED.period_end,calculation_method='bank_schedule',living_budget_exempt=true,
      source_type='bank_schedule',fulfillment_mode='dated_payment',liability_payment_schedule_id=EXCLUDED.liability_payment_schedule_id WHERE public.cash_flow_events.status NOT IN ('executed','partially_executed','cancelled');
  END LOOP;
 FOR v_obsolete IN SELECT e.id FROM public.cash_flow_events e WHERE e.source_type IN ('rule','bank_schedule') AND e.source_key IS NOT NULL
 AND e.event_date BETWEEN from_date AND to_date AND e.status NOT IN ('executed','partially_executed','cancelled') AND NOT(e.source_key=ANY(v_seen)) LOOP
  IF EXISTS(SELECT 1 FROM public.cash_flow_event_funding WHERE cash_flow_event_id=v_obsolete.id) THEN RAISE EXCEPTION 'event % has allocations: reconcile funding before removing its source',v_obsolete.id;END IF;
  UPDATE public.cash_flow_events SET status='cancelled' WHERE id=v_obsolete.id;
 END LOOP;
 UPDATE public.transactions t SET income_event_id=e.id FROM public.cash_flow_events e JOIN public.cash_flow_rules sr ON sr.id=e.rule_id
 WHERE t.transaction_type='income' AND t.income_event_id IS NULL AND e.event_type='income' AND e.status<>'cancelled'
 AND e.period_start=t.salary_period_start AND ((t.salary_component='advance' AND sr.rule_type='salary_advance') OR (t.salary_component='salary' AND sr.rule_type='salary_balance'));

END
$function$;

-- Component: database/functions/get_account_balance--329abeba8c.sql
CREATE OR REPLACE FUNCTION public.get_account_balance(p_account_id bigint, p_as_of date)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT public.get_account_balance(p_account_id,public.finance_day_end(p_as_of)) $function$;

-- Component: database/functions/get_account_balance--654dfdbb2e.sql
CREATE OR REPLACE FUNCTION public.get_account_balance(p_account_id bigint, p_as_of timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_base numeric; v_anchor timestamptz; v_open_date date;
BEGIN
 SELECT s.balance,s.balance_as_of INTO v_base,v_anchor FROM public.account_balance_snapshots s WHERE s.account_id=p_account_id AND s.balance_as_of<=p_as_of ORDER BY s.balance_as_of DESC LIMIT 1;
 IF v_base IS NULL THEN SELECT a.opening_balance,a.opening_balance_date INTO v_base,v_open_date FROM public.accounts a WHERE a.id=p_account_id; IF NOT FOUND THEN RETURN NULL; END IF; v_base:=COALESCE(v_base,0); v_anchor:=CASE WHEN v_open_date IS NOT NULL THEN public.finance_day_start(v_open_date)-interval '1 microsecond' ELSE '-infinity'::timestamptz END; END IF;
 RETURN v_base+COALESCE((SELECT SUM(CASE WHEN t.from_account_id=p_account_id THEN -t.amount WHEN t.to_account_id=p_account_id THEN t.amount ELSE 0 END) FROM public.transactions t WHERE (t.from_account_id=p_account_id OR t.to_account_id=p_account_id) AND t.occurred_at>v_anchor AND t.occurred_at<=p_as_of),0);
END $function$;

-- Component: database/functions/get_actual_cash--4d54a90000.sql
CREATE OR REPLACE FUNCTION public.get_actual_cash(p_as_of date)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT public.get_actual_cash(public.finance_day_end(p_as_of)) $function$;

-- Component: database/functions/get_actual_cash--f161cecaef.sql
CREATE OR REPLACE FUNCTION public.get_actual_cash(p_as_of timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT COALESCE(SUM(public.get_account_balance(a.id,p_as_of)),0) FROM public.accounts a WHERE a.is_active AND a.account_type IN ('bank','cash') $function$;

-- Component: database/functions/get_cash_flow_event_coverage--af94ef53c9.sql
CREATE OR REPLACE FUNCTION public.get_cash_flow_event_coverage(p_event_id bigint)
 RETURNS TABLE(planned_amount numeric, paid_amount numeric, funded_amount numeric, remaining_payment_amount numeric, remaining_funding_amount numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
SELECT s.amount,s.paid_amount,s.funded_amount,s.remaining_payment_amount,s.cash_still_required
FROM public.get_cash_flow_event_state_as_of(now()) s WHERE s.event_id=p_event_id;
$function$;

-- Component: database/functions/get_cash_flow_event_state_as_of--e6aad22f44.sql
CREATE OR REPLACE FUNCTION public.get_cash_flow_event_state_as_of(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(event_id bigint, event_date date, event_type text, amount numeric, description text, account_id bigint, liability_id bigint, status text, paid_amount numeric, funded_amount numeric, cash_committed_amount numeric, remaining_payment_amount numeric, cash_still_required numeric, derived_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
WITH x AS (
 SELECT e.id,e.event_date,e.event_type,e.amount,e.description,e.account_id,e.liability_id,e.status,
 coalesce(sum(f.amount) FILTER(WHERE f.relation_type='payment' AND t.occurred_at<=p_as_of),0) paid,
 coalesce(sum(f.amount) FILTER(WHERE f.relation_type='funding' AND t.occurred_at<=p_as_of),0) funded,
 coalesce(sum(f.amount) FILTER(WHERE t.occurred_at<=p_as_of AND fa.account_type IN ('bank','cash')),0) committed
 FROM public.cash_flow_events e LEFT JOIN public.cash_flow_event_funding f ON f.cash_flow_event_id=e.id
 LEFT JOIN public.transactions t ON t.id=f.transaction_id LEFT JOIN public.accounts fa ON fa.id=t.from_account_id GROUP BY e.id)
SELECT x.id,x.event_date,x.event_type,x.amount,x.description,x.account_id,x.liability_id,x.status,
 CASE WHEN x.event_type='income' THEN i.received_amount ELSE x.paid END,x.funded,x.committed,
 CASE WHEN x.event_type='income' THEN i.remaining_amount ELSE greatest(x.amount-x.paid,0) END,
 CASE WHEN x.event_type='income' OR x.status='cancelled' OR x.paid>=x.amount THEN 0 ELSE greatest(x.amount-x.committed,0) END,
 CASE WHEN x.event_type='income' THEN i.derived_status WHEN x.status='cancelled' THEN 'cancelled'
 WHEN x.paid>=x.amount THEN 'executed' WHEN x.paid>0 THEN 'partially_executed'
 WHEN x.committed>=x.amount THEN 'secured' WHEN x.committed>0 THEN 'partially_secured' ELSE 'planned' END
FROM x LEFT JOIN public.get_income_event_state_as_of(p_as_of) i ON i.event_id=x.id;
$function$;

-- Component: database/functions/get_credit_budget_position--a68ed80ef8.sql
CREATE OR REPLACE FUNCTION public.get_credit_budget_position(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(account_id bigint, account_name text, life_spend_total numeric, cash_repayments_total numeric, unsettled_budget_spend numeric, this_week_life_spend numeric, this_week_cash_repayments numeric, this_week_unsettled numeric, carryover_unsettled numeric, strategic_repayments numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
WITH cfg AS (
 SELECT public.finance_day_start((public.finance_setting_text('tracking_start_date','1970-01-01'))::date) start_ts,date_trunc('week',public.finance_business_date(p_as_of))::date week_start
),cc AS (
 SELECT a.id,a.name FROM public.accounts a WHERE a.is_active AND a.account_type='credit_card'
),mov AS (
 SELECT c.id account_id,t.occurred_at,t.id txid,t.transaction_date,t.amount delta_amount,t.amount life_amount,0::numeric repay_amount
 FROM cc c JOIN public.transactions t ON t.from_account_id=c.id CROSS JOIN cfg
 WHERE t.occurred_at BETWEEN cfg.start_ts AND p_as_of AND t.transaction_type='expense' AND t.budget_effect='life'
 UNION ALL
 SELECT c.id,t.occurred_at,t.id,t.transaction_date,-t.amount,0::numeric,t.amount
 FROM cc c JOIN public.transactions t ON t.to_account_id=c.id JOIN public.accounts fa ON fa.id=t.from_account_id CROSS JOIN cfg
 WHERE t.occurred_at BETWEEN cfg.start_ts AND p_as_of AND fa.account_type IN ('bank','cash') AND t.transaction_type IN ('transfer','debt_payment') AND t.reserve_effect<>'grace_repay'
),run AS (
 SELECT m.*,SUM(delta_amount) OVER(PARTITION BY account_id ORDER BY occurred_at,txid ROWS UNBOUNDED PRECEDING) cs FROM mov m
),stats AS (
 SELECT account_id,MAX(cs) FILTER(WHERE rn_desc=1) final_cs,LEAST(MIN(cs),0) min_cs
 FROM (SELECT r.*,ROW_NUMBER() OVER(PARTITION BY account_id ORDER BY occurred_at DESC,txid DESC) rn_desc FROM run r) z GROUP BY account_id
),agg AS (
 SELECT c.id,c.name,COALESCE(SUM(m.life_amount),0) life_total,COALESCE(SUM(m.repay_amount),0) repay_total,
   COALESCE(s.final_cs,0) final_cs,COALESCE(s.min_cs,0) min_cs,
   COALESCE(SUM(m.life_amount) FILTER(WHERE m.transaction_date BETWEEN cfg.week_start AND public.finance_business_date(p_as_of)),0) week_life,
   COALESCE(SUM(m.repay_amount) FILTER(WHERE m.transaction_date BETWEEN cfg.week_start AND public.finance_business_date(p_as_of)),0) week_repay
 FROM cc c CROSS JOIN cfg LEFT JOIN mov m ON m.account_id=c.id LEFT JOIN stats s ON s.account_id=c.id
 GROUP BY c.id,c.name,cfg.week_start,s.final_cs,s.min_cs
)
SELECT id,name,life_total,repay_total,GREATEST(final_cs-min_cs,0),week_life,week_repay,LEAST(GREATEST(final_cs-min_cs,0),week_life),GREATEST(GREATEST(final_cs-min_cs,0)-LEAST(GREATEST(final_cs-min_cs,0),week_life),0),GREATEST(repay_total-(life_total-GREATEST(final_cs-min_cs,0)),0)
FROM agg
$function$;

-- Component: database/functions/get_credit_cash_reserves--48133ca082.sql
CREATE OR REPLACE FUNCTION public.get_credit_cash_reserves(p_as_of timestamp with time zone, p_horizon_end date)
 RETURNS TABLE(account_id bigint, unpaid_life numeric, grace_outstanding numeric, scheduled_repayments numeric, additional_reserve numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 WITH grace AS (SELECT reserve_liability_id,sum(CASE reserve_effect WHEN 'grace_draw' THEN amount ELSE -amount END) amount FROM public.transactions WHERE reserve_effect<>'none' AND occurred_at<=p_as_of GROUP BY reserve_liability_id),
 scheduled AS (SELECT e.liability_id,sum(s.cash_still_required) amount FROM public.cash_flow_events e JOIN public.get_cash_flow_event_state_as_of(p_as_of)s ON s.event_id=e.id WHERE e.event_type='debt_payment' AND s.derived_status NOT IN ('executed','cancelled') AND e.event_date<=p_horizon_end GROUP BY e.liability_id)
 SELECT c.account_id,c.unsettled_budget_spend,coalesce(g.amount,0),coalesce(s.amount,0),greatest(c.unsettled_budget_spend+coalesce(g.amount,0)-coalesce(s.amount,0),0)
 FROM public.get_credit_budget_position(p_as_of)c LEFT JOIN public.liabilities l ON l.linked_account_id=c.account_id AND l.balance_model='revolving_account' AND l.status='active'
 LEFT JOIN grace g ON g.reserve_liability_id=l.id LEFT JOIN scheduled s ON s.liability_id=l.id;
$function$;

-- Component: database/functions/get_expense_category_lines--25428b0831.sql
CREATE OR REPLACE FUNCTION public.get_expense_category_lines(p_start date, p_end date)
 RETURNS TABLE(transaction_id bigint, transaction_date date, description text, category_id bigint, category_name text, amount numeric, allocation_source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with tx as (
    select t.* from public.transactions t
    where t.transaction_type='expense' and t.transaction_date between p_start and p_end
  ), alloc as (
    select a.transaction_id,a.category_id,a.amount,a.allocation_source
    from public.transaction_category_allocations a join tx on tx.id=a.transaction_id
  )
  select t.id,t.transaction_date,t.description,a.category_id,c.name,a.amount,a.allocation_source
  from tx t join alloc a on a.transaction_id=t.id join public.categories c on c.id=a.category_id
  union all
  select t.id,t.transaction_date,t.description,t.category_id,c.name,t.amount,'transaction'::text
  from tx t left join public.categories c on c.id=t.category_id
  where not exists(select 1 from alloc a where a.transaction_id=t.id)
  order by 2,1,5;
$function$;

-- Component: database/functions/get_financial_position--d043b30aa9.sql
CREATE OR REPLACE FUNCTION public.get_financial_position(p_as_of date, p_default_weekly_budget numeric DEFAULT 20000)
 RETURNS TABLE(as_of timestamp with time zone, actual_cash numeric, projected_cash numeric, current_week_budget numeric, remaining_living_budget numeric, living_budget_overrun numeric, active_purchase_reserve numeric, unsecured_obligations numeric, secured_obligations numeric, credit_expenses_over_budget numeric, free_cash numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT * FROM public.get_financial_position(public.finance_day_end(p_as_of),p_default_weekly_budget) $function$;

-- Component: database/functions/get_financial_position--6ee5ec6561.sql
CREATE OR REPLACE FUNCTION public.get_financial_position(p_as_of timestamp with time zone, p_default_weekly_budget numeric DEFAULT 20000)
 RETURNS TABLE(as_of timestamp with time zone, actual_cash numeric, projected_cash numeric, current_week_budget numeric, remaining_living_budget numeric, living_budget_overrun numeric, active_purchase_reserve numeric, unsecured_obligations numeric, secured_obligations numeric, credit_expenses_over_budget numeric, free_cash numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT p_as_of,v.actual_cash,v.projected_cash,v.current_week_budget,v.remaining_living_budget,GREATEST(v.current_week_spend-v.current_week_budget,0),v.planned_purchase_reserve,v.required_cash_flow_outflows,v.secured_future_outflows,v.credit_budget_additional_reserve,v.free_cash FROM public.get_financial_position_at(public.finance_business_date(p_as_of),p_as_of,p_default_weekly_budget) v
$function$;

-- Component: database/functions/get_financial_position_at--9f14d7d31e.sql
CREATE OR REPLACE FUNCTION public.get_financial_position_at(p_as_of date, p_cutoff timestamp with time zone, p_default_weekly_budget numeric DEFAULT NULL::numeric)
 RETURNS TABLE(as_of date, actual_cash numeric, expected_income numeric, required_cash_flow_outflows numeric, secured_future_outflows numeric, projected_cash numeric, current_week_budget numeric, current_week_spend numeric, remaining_living_budget numeric, future_living_budget numeric, credit_budget_reserve numeric, credit_budget_additional_reserve numeric, planned_purchase_reserve numeric, free_cash numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_now_ts timestamptz:=p_cutoff;v_today date:=public.finance_business_date(v_now_ts);v_cutoff timestamptz;v_anchor_date date;v_week_start date;v_budget numeric;v_spend numeric;v_remain numeric;v_future_budget numeric:=0;v_w date;v_wb numeric;v_income numeric:=0;v_outflows numeric:=0;v_secured numeric:=0;v_projected numeric;v_card_reserve numeric:=0;v_card_additional numeric:=0;v_purchases numeric:=0;r record;v_scheduled numeric;v_actual_cash numeric;
BEGIN
 v_cutoff:=p_cutoff;
 v_anchor_date:=public.finance_business_date(v_cutoff);v_week_start:=date_trunc('week',v_anchor_date)::date;
 SELECT public.get_actual_cash(v_cutoff) INTO v_actual_cash;
 v_budget:=COALESCE((SELECT lb.amount FROM public.living_budgets lb WHERE lb.week_start=v_week_start),p_default_weekly_budget,public.finance_setting_numeric('default_weekly_budget',20000));
 SELECT COALESCE(SUM(t.amount),0) INTO v_spend FROM public.transactions t WHERE t.budget_effect='life' AND t.occurred_at<=v_cutoff AND t.transaction_date BETWEEN v_week_start AND v_anchor_date;
 SELECT remaining_reserve INTO v_remain FROM public.get_living_budget_reserve(v_week_start,v_cutoff,p_default_weekly_budget);
 IF p_as_of>=v_today THEN
   SELECT COALESCE(SUM(i.remaining_amount),0) INTO v_income FROM public.cash_flow_events e JOIN public.get_income_event_state_as_of(v_cutoff) i ON i.event_id=e.id WHERE i.derived_status NOT IN ('cancelled','executed') AND e.event_date BETWEEN v_today AND p_as_of;
   SELECT COALESCE(SUM(s.cash_still_required),0),COALESCE(SUM(s.amount) FILTER(WHERE s.cash_still_required=0 AND s.remaining_payment_amount>0),0)
   INTO v_outflows,v_secured
   FROM public.get_cash_flow_event_state_as_of(v_now_ts) s
   JOIN public.cash_flow_events e ON e.id=s.event_id
   WHERE s.event_type IN ('expense','debt_payment','planned_expense')
     AND s.event_date<=p_as_of AND s.derived_status<>'cancelled'
     AND (s.event_type='debt_payment' OR e.living_budget_exempt);
   v_w:=date_trunc('week',v_today)::date+7;
   WHILE v_w<=p_as_of LOOP
     SELECT COALESCE((SELECT lb.amount FROM public.living_budgets lb WHERE lb.week_start=v_w),COALESCE(p_default_weekly_budget,public.finance_setting_numeric('default_weekly_budget',20000))) INTO v_wb;
     SELECT remaining_reserve INTO v_wb FROM public.get_living_budget_reserve(v_w,v_cutoff,p_default_weekly_budget);v_future_budget:=v_future_budget+v_wb;v_w:=v_w+7;
   END LOOP;
 ELSE
   SELECT COALESCE(SUM(s.cash_still_required),0),COALESCE(SUM(s.amount) FILTER(WHERE s.cash_still_required=0 AND s.remaining_payment_amount>0),0)
   INTO v_outflows,v_secured
   FROM public.get_cash_flow_event_state_as_of(v_cutoff) s
   JOIN public.cash_flow_events e ON e.id=s.event_id
   WHERE s.event_type IN ('expense','debt_payment','planned_expense')
     AND s.event_date<=p_as_of AND s.derived_status<>'cancelled'
     AND (s.event_type='debt_payment' OR e.living_budget_exempt);
 END IF;
 v_projected:=v_actual_cash+v_income-v_outflows;
 SELECT coalesce(sum(unpaid_life+grace_outstanding),0),coalesce(sum(additional_reserve),0) INTO v_card_reserve,v_card_additional FROM public.get_credit_cash_reserves(v_cutoff,p_as_of);

 SELECT COALESCE(SUM(pp.planned_amount),0) INTO v_purchases FROM public.planned_purchases pp WHERE pp.created_at<=v_cutoff AND pp.status<>'cancelled' AND (pp.closed_at IS NULL OR pp.closed_at>v_cutoff);
 RETURN QUERY SELECT p_as_of,v_actual_cash,v_income,v_outflows,v_secured,v_projected,v_budget,v_spend,v_remain,v_future_budget,v_card_reserve,v_card_additional,v_purchases,v_projected-v_remain-v_future_budget-v_card_additional-v_purchases;
END
$function$;

-- Component: database/functions/get_financial_position_v2--588bed1dca.sql
CREATE OR REPLACE FUNCTION public.get_financial_position_v2(p_as_of date, p_default_weekly_budget numeric DEFAULT NULL::numeric)
 RETURNS TABLE(as_of date, actual_cash numeric, expected_income numeric, required_cash_flow_outflows numeric, secured_future_outflows numeric, projected_cash numeric, current_week_budget numeric, current_week_spend numeric, remaining_living_budget numeric, future_living_budget numeric, credit_budget_reserve numeric, credit_budget_additional_reserve numeric, planned_purchase_reserve numeric, free_cash numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 RETURN QUERY SELECT * FROM public.get_financial_position_at(p_as_of,
 CASE WHEN p_as_of<public.finance_business_date(now()) THEN public.finance_day_end(p_as_of) ELSE now() END,p_default_weekly_budget);
END
$function$;

-- Component: database/functions/get_free_cash--5de924fe5e.sql
CREATE OR REPLACE FUNCTION public.get_free_cash(p_as_of date)
 RETURNS numeric
 LANGUAGE sql
