 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT free_cash_until_next_income FROM public.get_liquidity_until_next_income(public.finance_day_end(p_as_of),NULL) $function$;

-- Component: database/functions/get_free_cash--5ed941717d.sql
CREATE OR REPLACE FUNCTION public.get_free_cash(p_as_of timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT free_cash_until_next_income FROM public.get_liquidity_until_next_income(p_as_of,NULL) $function$;

-- Component: database/functions/get_income_event_state_as_of--e07cdd98ff.sql
CREATE OR REPLACE FUNCTION public.get_income_event_state_as_of(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(event_id bigint, received_amount numeric, remaining_amount numeric, derived_status text, last_received_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 WITH a AS (
 SELECT e.id,e.amount,e.status,e.income_completed_at,coalesce(sum(t.amount) FILTER(WHERE t.occurred_at<=p_as_of),0) received,
 max(t.occurred_at) FILTER(WHERE t.occurred_at<=p_as_of) last_at
 FROM public.cash_flow_events e LEFT JOIN public.transactions t ON t.income_event_id=e.id AND t.transaction_type='income'
 WHERE e.event_type='income' GROUP BY e.id)
 SELECT id,received,CASE WHEN status='cancelled' OR income_completed_at<=p_as_of THEN 0 ELSE greatest(amount-received,0) END,
 CASE WHEN status='cancelled' THEN 'cancelled' WHEN received>=amount OR income_completed_at<=p_as_of THEN 'executed'
 WHEN received>0 THEN 'partially_executed' ELSE 'planned' END,last_at FROM a;
$function$;

-- Component: database/functions/get_liability_balance--4540d0944f.sql
CREATE OR REPLACE FUNCTION public.get_liability_balance(p_liability_id bigint, p_as_of date)
 RETURNS TABLE(principal_balance numeric, accrued_interest numeric, fees_due numeric, total_debt numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT * FROM public.get_liability_balance(p_liability_id,public.finance_day_end(p_as_of)) $function$;

-- Component: database/functions/get_liability_balance--8d1c73d395.sql
CREATE OR REPLACE FUNCTION public.get_liability_balance(p_liability_id bigint, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(principal_balance numeric, accrued_interest numeric, fees_due numeric, total_debt numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_model text; v_account bigint; v_p numeric:=0; v_i numeric:=0; v_f numeric:=0; v_anchor timestamptz;
BEGIN
 SELECT balance_model,linked_account_id INTO v_model,v_account FROM public.liabilities WHERE id=p_liability_id; IF NOT FOUND THEN RETURN; END IF;
 IF v_model='revolving_account' THEN v_p:=GREATEST(-COALESCE(public.get_account_balance(v_account,p_as_of),0),0); RETURN QUERY SELECT v_p,0::numeric,0::numeric,v_p; RETURN; END IF;
 SELECT s.principal_balance,s.accrued_interest,s.fees_due,s.balance_as_of INTO v_p,v_i,v_f,v_anchor FROM public.liability_balance_snapshots s WHERE s.liability_id=p_liability_id AND s.balance_as_of<=p_as_of ORDER BY s.balance_as_of DESC LIMIT 1;
 IF v_anchor IS NULL THEN RETURN QUERY SELECT NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric; RETURN; END IF;
 SELECT v_p+COALESCE(SUM(CASE m.movement_type WHEN 'principal_increase' THEN m.amount WHEN 'principal_payment' THEN -m.amount WHEN 'principal_adjustment' THEN m.direction*m.amount ELSE 0 END),0),v_i+COALESCE(SUM(CASE m.movement_type WHEN 'interest_accrual' THEN m.amount WHEN 'interest_payment' THEN -m.amount WHEN 'interest_adjustment' THEN m.direction*m.amount ELSE 0 END),0),v_f+COALESCE(SUM(CASE m.movement_type WHEN 'fee_accrual' THEN m.amount WHEN 'fee_payment' THEN -m.amount WHEN 'fee_adjustment' THEN m.direction*m.amount ELSE 0 END),0) INTO v_p,v_i,v_f FROM public.liability_movements m WHERE m.liability_id=p_liability_id AND m.effective_at>v_anchor AND m.effective_at<=p_as_of;
 v_p:=GREATEST(v_p,0);v_i:=GREATEST(v_i,0);v_f:=GREATEST(v_f,0); RETURN QUERY SELECT v_p,v_i,v_f,v_p+v_i+v_f;
END $function$;

-- Component: database/functions/get_liability_balance_details--0017571ee7.sql
CREATE OR REPLACE FUNCTION public.get_liability_balance_details(p_liability_id bigint, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(total_debt numeric, principal_balance numeric, accrued_interest numeric, fees_due numeric, components_known boolean, components_as_of timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l public.liabilities;s public.liability_balance_snapshots;b record;
BEGIN
 SELECT * INTO l FROM public.liabilities WHERE id=p_liability_id;IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO b FROM public.get_liability_balance(p_liability_id,p_as_of);
 IF l.balance_model='installment' THEN RETURN QUERY SELECT b.total_debt,b.principal_balance,b.accrued_interest,b.fees_due,b.total_debt IS NOT NULL,p_as_of;RETURN;END IF;
 SELECT * INTO s FROM public.liability_balance_snapshots WHERE liability_id=p_liability_id AND balance_as_of<=p_as_of ORDER BY balance_as_of DESC LIMIT 1;
 IF s.balance_as_of=p_as_of AND abs(b.total_debt-(s.principal_balance+s.accrued_interest+s.fees_due))<0.005 THEN
 RETURN QUERY SELECT b.total_debt,s.principal_balance,s.accrued_interest,s.fees_due,true,s.balance_as_of;
 ELSE RETURN QUERY SELECT b.total_debt,NULL::numeric,NULL::numeric,NULL::numeric,false,s.balance_as_of;END IF;
END $function$;

-- Component: database/functions/get_liquidity_until_next_income--5a43c09635.sql
CREATE OR REPLACE FUNCTION public.get_liquidity_until_next_income(p_as_of timestamp with time zone DEFAULT now(), p_default_weekly_budget numeric DEFAULT NULL::numeric)
 RETURNS TABLE(as_of timestamp with time zone, business_date date, next_income_date date, next_income_description text, next_income_amount numeric, actual_cash numeric, required_outflows_before_income numeric, remaining_living_budget numeric, future_living_budget numeric, planned_purchase_reserve numeric, free_cash_until_next_income numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_today date := public.finance_business_date(p_as_of);
  v_next_income_date date;
  v_next_income_description text;
  v_next_income_amount numeric;
  v_actual_cash numeric;
  v_outflows numeric := 0;
  v_week_start date;
  v_budget numeric;
  v_spend numeric;
  v_remain numeric;
  v_future_budget numeric := 0;
  v_w date;
  v_horizon_end date;
  v_wb numeric;
  v_purchases numeric := 0; v_credit_reserve numeric:=0;
begin
  select e.event_date,e.description,ist.remaining_amount
    into v_next_income_date,v_next_income_description,v_next_income_amount
  from public.cash_flow_events e JOIN public.get_income_event_state_as_of(p_as_of) ist ON ist.event_id=e.id
  where e.event_type='income'
    and ist.derived_status not in ('cancelled','executed')
    and e.event_date>=v_today

  order by e.event_date,e.id
  limit 1;

  select public.get_actual_cash(p_as_of) into v_actual_cash;

  v_week_start:=date_trunc('week',v_today)::date;
  select coalesce((select lb.amount from public.living_budgets lb where lb.week_start=v_week_start),
                  p_default_weekly_budget,
                  public.finance_setting_numeric('default_weekly_budget',20000))
    into v_budget;

  select coalesce(sum(t.amount),0) into v_spend
  from public.transactions t
  where t.budget_effect='life'
    and t.occurred_at<=p_as_of
    and t.transaction_date between v_week_start and v_today;
  SELECT remaining_reserve INTO v_remain FROM public.get_living_budget_reserve(v_week_start,p_as_of,p_default_weekly_budget);

  if v_next_income_date is not null then
    select coalesce(sum(s.cash_still_required),0) into v_outflows
    from public.get_cash_flow_event_state_as_of(p_as_of) s
    join public.cash_flow_events e on e.id=s.event_id
    where s.event_type in ('expense','debt_payment','planned_expense')
      and s.event_date<v_next_income_date
      and s.derived_status not in ('cancelled','executed')
      and (s.event_type='debt_payment' or e.living_budget_exempt);

    v_horizon_end:=v_next_income_date-1;
    v_w:=v_week_start+7;
    while v_w<=v_horizon_end loop
      select coalesce((select lb.amount from public.living_budgets lb where lb.week_start=v_w),
                      coalesce(p_default_weekly_budget,public.finance_setting_numeric('default_weekly_budget',20000)))
        into v_wb;
      SELECT remaining_reserve INTO v_wb FROM public.get_living_budget_reserve(v_w,p_as_of,p_default_weekly_budget);
      v_future_budget:=v_future_budget+v_wb;
      v_w:=v_w+7;
    end loop;
  else
    v_outflows:=null;
    v_future_budget:=null;
  end if;

  select coalesce(sum(pp.planned_amount),0) into v_purchases
  from public.planned_purchases pp
  where pp.created_at<=p_as_of
    and pp.status<>'cancelled'
    and (pp.closed_at is null or pp.closed_at>p_as_of);

  SELECT coalesce(sum(additional_reserve),0) INTO v_credit_reserve FROM public.get_credit_cash_reserves(p_as_of,v_next_income_date-1);
  return query
  select p_as_of,v_today,v_next_income_date,v_next_income_description,v_next_income_amount,
         v_actual_cash,v_outflows,v_remain,v_future_budget,v_purchases,
         case when v_next_income_date is null then null
              else v_actual_cash-v_outflows-v_remain-v_future_budget-v_purchases-v_credit_reserve end;
end
$function$;

-- Component: database/functions/get_living_budget_reserve--e27d063804.sql
CREATE OR REPLACE FUNCTION public.get_living_budget_reserve(p_week_start date, p_as_of timestamp with time zone, p_default_budget numeric DEFAULT NULL::numeric)
 RETURNS TABLE(budget_amount numeric, spent_amount numeric, earmarked_amount numeric, remaining_reserve numeric, overrun numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 WITH b AS (SELECT coalesce((SELECT amount FROM public.living_budgets WHERE week_start=p_week_start),p_default_budget,public.finance_setting_numeric('default_weekly_budget',20000)) amount),
 spent AS (SELECT coalesce(sum(amount),0) amount FROM public.transactions WHERE budget_effect='life' AND transaction_date>=p_week_start AND transaction_date<p_week_start+7 AND occurred_at<=p_as_of),
 earmarked AS (SELECT coalesce(sum(greatest(s.funded_amount-s.paid_amount,0)),0) amount FROM public.cash_flow_events e JOIN public.get_cash_flow_event_state_as_of(p_as_of)s ON s.event_id=e.id WHERE e.event_type IN ('expense','planned_expense') AND NOT e.living_budget_exempt AND s.derived_status<>'cancelled' AND e.event_date>=p_week_start AND e.event_date<p_week_start+7)
 SELECT b.amount,spent.amount,earmarked.amount,greatest(b.amount-spent.amount-earmarked.amount,0),greatest(spent.amount-b.amount,0) FROM b,spent,earmarked;
$function$;

-- Component: database/functions/get_obligations_until_next_income--67aba6d215.sql
CREATE OR REPLACE FUNCTION public.get_obligations_until_next_income(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(next_income_date date, event_id bigint, event_date date, description text, amount numeric, remaining_payment_amount numeric, cash_still_required numeric, derived_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with ni as (
  select e.event_date
  from public.cash_flow_events e JOIN public.get_income_event_state_as_of(p_as_of) ist ON ist.event_id=e.id
  where e.event_type='income'
    and ist.derived_status not in ('cancelled','executed')
    and e.event_date >= public.finance_business_date(p_as_of)

  order by e.event_date,e.id
  limit 1
)
select ni.event_date,
       s.event_id,
       s.event_date,
       s.description,
       s.amount,
       s.remaining_payment_amount,
       s.cash_still_required,
       s.derived_status
from ni
join public.get_cash_flow_event_state_as_of(p_as_of) s on true
where s.event_type in ('expense','debt_payment','planned_expense')
  and s.event_date < ni.event_date
  and s.derived_status not in ('cancelled','executed')
order by s.event_date,s.description;
$function$;

-- Component: database/functions/get_settlement_attention--8b310d39ab.sql
CREATE OR REPLACE FUNCTION public.get_settlement_attention(p_as_of date DEFAULT finance_business_date(now()))
 RETURNS TABLE(event_id bigint, event_date date, description text, amount numeric, paid_amount numeric, funded_amount numeric, cash_still_required numeric, remaining_payment_amount numeric, derived_status text, timing_status text, attention_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    s.event_id,
    s.event_date,
    s.description,
    s.amount,
    s.paid_amount,
    s.funded_amount,
    s.cash_still_required,
    s.remaining_payment_amount,
    s.derived_status,
    case
      when s.event_date < p_as_of and s.derived_status not in ('executed','cancelled') then 'overdue_unconfirmed'
      when s.event_date = p_as_of then 'due_today'
      else 'other'
    end as timing_status,
    case
      when s.derived_status='executed' then 'исполнено'
      when s.paid_amount>0 and s.remaining_payment_amount>0 and s.cash_still_required=0 then 'частично списано, остаток обеспечен'
      when s.paid_amount>0 and s.remaining_payment_amount>0 then 'частично списано, требуется доплата/обеспечение'
      when s.cash_still_required=0 and s.remaining_payment_amount>0 then 'обеспечено, списание не подтверждено'
      when s.cash_still_required>0 then 'не обеспечено'
      else s.derived_status
    end as attention_status
  from public.get_cash_flow_event_state_as_of(public.finance_day_end(p_as_of)) s
  where s.event_type in ('expense','debt_payment','planned_expense')
    and s.derived_status <> 'cancelled'
    and (
      s.event_date = p_as_of
      or (s.event_date < p_as_of and s.derived_status <> 'executed')
    )
  order by s.event_date,s.description;
$function$;

-- Component: database/functions/get_status_until_next_income--8d89e6dc13.sql
CREATE OR REPLACE FUNCTION public.get_status_until_next_income(p_as_of timestamp with time zone DEFAULT now(), p_default_weekly_budget numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  l record;
  v_today date:=public.finance_business_date(p_as_of);
  v_cash jsonb;
  v_today_events jsonb;
  v_controls jsonb;
  v_future jsonb;
  v_integrity jsonb;
  v_integrity_errors integer;
  v_week_start date;
  v_week_budget numeric;
  v_week_spend numeric;
  v_week_remaining numeric;
  v_week_overrun numeric;
begin
  select * into l from public.get_liquidity_until_next_income(p_as_of,p_default_weekly_budget);

  v_week_start:=date_trunc('week',v_today)::date;
  select coalesce((select lb.amount from public.living_budgets lb where lb.week_start=v_week_start),
                  p_default_weekly_budget,
                  public.finance_setting_numeric('default_weekly_budget',20000))
    into v_week_budget;
  select coalesce(sum(t.amount),0) into v_week_spend
  from public.transactions t
  where t.budget_effect='life' and t.occurred_at<=p_as_of and t.transaction_date between v_week_start and v_today;
  v_week_remaining:=greatest(v_week_budget-v_week_spend,0);
  v_week_overrun:=greatest(v_week_spend-v_week_budget,0);

  select coalesce(jsonb_agg(jsonb_build_object(
           'account_id',x.id,'name',x.name,
           'short_name',case when x.account_type='cash' then 'нал' else x.name end,
           'account_type',x.account_type,'balance',x.balance
         ) order by case when x.account_type='cash' then 0 when x.account_type='bank' then 1 else 2 end,x.id),'[]'::jsonb)
    into v_cash
  from (
    select a.id,a.name,a.account_type,public.get_account_balance(a.id,p_as_of) balance
    from public.accounts a where a.is_active and a.account_type in ('bank','cash')
  ) x;

  with st as (select * from public.get_cash_flow_event_state_as_of(p_as_of))
  select coalesce(jsonb_agg(jsonb_build_object(
           'event_id',s.event_id,'date',s.event_date,'description',s.description,
           'amount',s.remaining_payment_amount,'cash_still_required',s.cash_still_required,
           'derived_status',s.derived_status,'living_budget_exempt',e.living_budget_exempt,
           'coverage',case when s.cash_still_required=0 then 'funded'
                           when s.event_type in ('expense','planned_expense') and not e.living_budget_exempt then 'living_budget'
                           else 'unsecured' end,
           'counts_against_free_cash',case when s.event_type='debt_payment' or e.living_budget_exempt then true else false end
         ) order by s.description),'[]'::jsonb)
    into v_today_events
  from st s join public.cash_flow_events e on e.id=s.event_id
  where s.event_date=v_today and s.event_type in ('expense','debt_payment','planned_expense')
    and s.derived_status not in ('executed','cancelled');

  with st as (select * from public.get_cash_flow_event_state_as_of(p_as_of))
  select coalesce(jsonb_agg(jsonb_build_object(
           'event_id',s.event_id,'date',s.event_date,'description',s.description,
           'amount',s.remaining_payment_amount,'cash_still_required',s.cash_still_required,
           'derived_status',s.derived_status,
           'attention',case when s.cash_still_required>0 then 'requires_action' else 'secured_unconfirmed' end
         ) order by s.event_date,s.description),'[]'::jsonb)
    into v_controls
  from st s
  where s.event_date<v_today and s.event_type in ('expense','debt_payment','planned_expense')
    and s.derived_status not in ('executed','cancelled');

  with st as (select * from public.get_cash_flow_event_state_as_of(p_as_of))
  select coalesce(jsonb_agg(jsonb_build_object(
           'event_id',s.event_id,'date',s.event_date,'description',s.description,
           'amount',s.remaining_payment_amount,'cash_still_required',s.cash_still_required,
           'derived_status',s.derived_status,'living_budget_exempt',e.living_budget_exempt,
           'coverage',case when s.cash_still_required=0 then 'funded'
                           when s.event_type in ('expense','planned_expense') and not e.living_budget_exempt then 'living_budget'
                           else 'unsecured' end,
           'counts_against_free_cash',case when s.event_type='debt_payment' or e.living_budget_exempt then true else false end
         ) order by s.event_date,s.description),'[]'::jsonb)
    into v_future
  from st s join public.cash_flow_events e on e.id=s.event_id
  where l.next_income_date is not null and s.event_date>v_today and s.event_date<l.next_income_date
    and s.event_type in ('expense','debt_payment','planned_expense') and s.derived_status not in ('executed','cancelled');

  select coalesce(jsonb_agg(jsonb_build_object('severity',q.severity,'code',q.code,'entity_type',q.entity_type,'entity_id',q.entity_id,'message',q.message,'details',q.details)),'[]'::jsonb),
         count(*) filter(where q.severity='error')
    into v_integrity,v_integrity_errors
  from public.finance_integrity_check(p_as_of) q;

  return jsonb_build_object(
    'status_version','cashflow_until_next_income_v3','as_of',p_as_of,'business_date',v_today,
    'integrity_ok',coalesce(v_integrity_errors,0)=0,'integrity_issues',v_integrity,
    'cash',jsonb_build_object('actual_cash',l.actual_cash,'breakdown',v_cash),
    'next_income',jsonb_build_object('date',l.next_income_date,'description',l.next_income_description,'amount',l.next_income_amount),
    'weekly_budget',jsonb_build_object('week_start',v_week_start,'budget',v_week_budget,'spend',v_week_spend,'remaining',v_week_remaining,'overrun',v_week_overrun),
    'liquidity',jsonb_build_object(
      'free_cash_until_next_income',l.free_cash_until_next_income,
      'required_outflows_before_income',l.required_outflows_before_income,
      'remaining_living_budget',l.remaining_living_budget,
      'future_living_budget',l.future_living_budget,
      'planned_purchase_reserve',l.planned_purchase_reserve,'credit_reserve',(SELECT coalesce(sum(additional_reserve),0) FROM public.get_credit_cash_reserves(p_as_of,l.next_income_date-1))),
    'today',v_today_events,'controls',v_controls,'obligations_until_next_income',v_future);
end
$function$;

-- Component: database/functions/get_upcoming_payments--cf8a6c80ca.sql
CREATE OR REPLACE FUNCTION public.get_upcoming_payments(p_days integer DEFAULT 10)
 RETURNS TABLE(event_id bigint, event_date date, description text, amount numeric, secured boolean, security_transaction_id bigint, security_note text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT s.event_id,s.event_date,s.description,s.amount,(s.cash_still_required=0),(SELECT f.transaction_id FROM public.cash_flow_event_funding f JOIN public.transactions t ON t.id=f.transaction_id WHERE f.cash_flow_event_id=s.event_id ORDER BY t.occurred_at DESC,f.id DESC LIMIT 1),CASE WHEN s.cash_still_required=0 THEN 'Деньги уже выведены из свободного cash / платёж обеспечен' WHEN s.cash_committed_amount>0 THEN 'Частично обеспечено; требуется ещё '||s.cash_still_required::text ELSE 'Требуется обеспечить '||s.cash_still_required::text END FROM public.cash_flow_event_state s WHERE s.event_date BETWEEN public.finance_business_date(now()) AND public.finance_business_date(now())+p_days AND s.event_type IN ('expense','debt_payment','planned_expense') AND s.derived_status NOT IN ('cancelled','executed') ORDER BY s.event_date,s.description
$function$;

-- Component: database/functions/link_funding--183bf77d8a.sql
CREATE OR REPLACE FUNCTION public.link_funding(p_event_id bigint, p_transaction_id bigint, p_amount numeric)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT public.link_funding(p_event_id,p_transaction_id,p_amount,'funding') $function$;

-- Component: database/functions/link_funding--baaab7d6e0.sql
CREATE OR REPLACE FUNCTION public.link_funding(p_event_id bigint, p_transaction_id bigint, p_amount numeric, p_relation_type text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ BEGIN IF p_amount<=0 THEN RAISE EXCEPTION 'p_amount must be > 0';END IF;IF p_relation_type NOT IN ('funding','payment') THEN RAISE EXCEPTION 'invalid relation_type';END IF;INSERT INTO public.cash_flow_event_funding(cash_flow_event_id,transaction_id,amount,relation_type) VALUES(p_event_id,p_transaction_id,p_amount,p_relation_type);PERFORM public.refresh_cash_flow_event_status(p_event_id);END $function$;

-- Component: database/functions/normalize_credit_card_payment_semantics--4d193efffb.sql
CREATE OR REPLACE FUNCTION public.normalize_credit_card_payment_semantics()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_to_type text;
  v_from_type text;
  v_liability bigint;
  v_debt_category bigint;
BEGIN
  SELECT account_type INTO v_to_type FROM public.accounts WHERE id=NEW.to_account_id;
  SELECT account_type INTO v_from_type FROM public.accounts WHERE id=NEW.from_account_id;

  IF v_to_type='credit_card' AND v_from_type IN ('bank','cash') AND NEW.transaction_type IN ('transfer','debt_payment') THEN
    SELECT id INTO v_liability
    FROM public.liabilities
    WHERE balance_model='revolving_account' AND linked_account_id=NEW.to_account_id AND status='active'
    ORDER BY id LIMIT 1;

    SELECT id INTO v_debt_category
    FROM public.categories
    WHERE category_type='debt' AND is_active
    ORDER BY CASE WHEN name='Погашение долга' THEN 0 ELSE 1 END,id LIMIT 1;

    NEW.transaction_type:='debt_payment';
    NEW.liability_id:=COALESCE(v_liability,NEW.liability_id);
    NEW.category_id:=COALESCE(NEW.category_id,v_debt_category);
    NEW.budget_effect:='none';
  END IF;
  RETURN NEW;
END
$function$;

-- Component: database/functions/normalize_payment_buffer_funding_semantics--16ab0a0576.sql
CREATE OR REPLACE FUNCTION public.normalize_payment_buffer_funding_semantics()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_from_type text;
  v_to_type text;
begin
  if new.from_account_id is null or new.to_account_id is null then
    return new;
  end if;
  select account_type into v_from_type from public.accounts where id=new.from_account_id;
  select account_type into v_to_type from public.accounts where id=new.to_account_id;
  if v_from_type in ('bank','cash') and v_to_type='payment_buffer' and new.transaction_type='debt_payment' then
    new.transaction_type:='transfer';
    new.budget_effect:='none';
  end if;
  return new;
end
$function$;

-- Component: database/functions/normalize_transaction_budget_effect--9e6add9034.sql
CREATE OR REPLACE FUNCTION public.normalize_transaction_budget_effect()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
IF TG_OP='UPDATE' THEN
 IF NEW.occurred_at IS DISTINCT FROM OLD.occurred_at AND NEW.transaction_date IS NOT DISTINCT FROM OLD.transaction_date THEN NEW.transaction_date:=public.finance_business_date(NEW.occurred_at);
 ELSIF NEW.transaction_date IS DISTINCT FROM OLD.transaction_date AND NEW.occurred_at IS NOT DISTINCT FROM OLD.occurred_at THEN
 NEW.occurred_at:=(NEW.transaction_date+(OLD.occurred_at AT TIME ZONE public.finance_setting_text('business_timezone','Europe/Moscow'))::time) AT TIME ZONE public.finance_setting_text('business_timezone','Europe/Moscow');
 END IF;
END IF;
IF NEW.occurred_at IS NULL THEN NEW.occurred_at:=COALESCE(public.finance_day_start(NEW.transaction_date)+interval '12 hours',now());END IF;IF NEW.transaction_date IS NULL THEN NEW.transaction_date:=public.finance_business_date(NEW.occurred_at);END IF;IF NEW.budget_effect IS NULL THEN NEW.budget_effect:=CASE WHEN NEW.transaction_type='expense' THEN 'life' ELSE 'none' END;END IF;IF NEW.transaction_type<>'expense' AND NEW.budget_effect='life' THEN NEW.budget_effect:='none';END IF;IF NEW.transaction_type='income' AND NEW.salary_component IS NULL THEN IF NEW.description ILIKE '%аванс%' THEN NEW.salary_component:='advance';ELSIF NEW.description ILIKE '%отпускн%' THEN NEW.salary_component:='vacation';ELSIF NEW.description ILIKE '%зарплат%' THEN NEW.salary_component:='salary';END IF;END IF;IF NEW.salary_component IN ('advance','vacation') AND NEW.salary_period_start IS NULL THEN NEW.salary_period_start:=date_trunc('month',NEW.transaction_date)::date;END IF;IF NEW.salary_component='salary' AND NEW.salary_period_start IS NULL THEN NEW.salary_period_start:=date_trunc('month',NEW.transaction_date-interval '1 month')::date;END IF;
IF NEW.transaction_date<>public.finance_business_date(NEW.occurred_at) THEN RAISE EXCEPTION 'transaction_date must match occurred_at in business timezone'; END IF;
IF NEW.transaction_type<>'income' THEN NEW.salary_component:=NULL;NEW.salary_period_start:=NULL;NEW.income_event_id:=NULL;
ELSIF NEW.salary_component IN ('advance','salary') THEN
 IF TG_OP='INSERT' OR NEW.salary_component IS DISTINCT FROM OLD.salary_component OR NEW.salary_period_start IS DISTINCT FROM OLD.salary_period_start OR NEW.income_event_id IS NULL THEN
 SELECT e.id INTO NEW.income_event_id FROM public.cash_flow_events e JOIN public.cash_flow_rules r ON r.id=e.rule_id
 WHERE e.event_type='income' AND e.status<>'cancelled' AND e.period_start=NEW.salary_period_start
 AND r.rule_type=CASE NEW.salary_component WHEN 'advance' THEN 'salary_advance' ELSE 'salary_balance' END ORDER BY e.id LIMIT 1;
 END IF;
END IF;
RETURN NEW;END $function$;

-- Component: database/functions/rebuild_debt_payment_movements--cadf8bb48d.sql
CREATE OR REPLACE FUNCTION public.rebuild_debt_payment_movements(p_liability_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;b record;v_i numeric;v_f numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
 DELETE FROM public.liability_movements WHERE liability_id=p_liability_id AND debt_payment_detail_id IS NOT NULL;
 FOR r IN SELECT d.*,t.occurred_at FROM public.debt_payment_details d JOIN public.transactions t ON t.id=d.transaction_id WHERE d.liability_id=p_liability_id ORDER BY t.occurred_at,t.id LOOP
  SELECT * INTO b FROM public.get_liability_balance(p_liability_id,r.occurred_at);
  IF b.total_debt IS NULL THEN RAISE EXCEPTION 'initial liability snapshot required for % before %',p_liability_id,r.occurred_at; END IF;
  v_i:=greatest(r.interest_amount-coalesce(b.accrued_interest,0),0);v_f:=greatest(r.fee_amount-coalesce(b.fees_due,0),0);
  INSERT INTO public.liability_movements(liability_id,effective_at,movement_type,amount,transaction_id,cash_flow_event_id,debt_payment_detail_id,notes)
  SELECT r.liability_id,r.occurred_at,x.kind,x.amount,r.transaction_id,r.cash_flow_event_id,r.id,'Derived from debt payment detail'
  FROM (VALUES ('interest_accrual',v_i),('fee_accrual',v_f),('principal_payment',r.principal_amount),('interest_payment',r.interest_amount),('fee_payment',r.fee_amount)) x(kind,amount) WHERE x.amount>0;
 END LOOP;
 PERFORM public.sync_liability_principal_cache(p_liability_id);
END $function$;

-- Component: database/functions/reconcile_credit_card_minimum--ea61b8cf4b.sql
CREATE OR REPLACE FUNCTION public.reconcile_credit_card_minimum(p_event_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  e public.cash_flow_events;
  l public.liabilities;
  r record;
  v_remaining numeric;
  v_tx_used numeric;
  v_available numeric;
  v_alloc numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
  SELECT * INTO e FROM public.cash_flow_events WHERE id=p_event_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cash flow event % not found',p_event_id; END IF;
  IF e.fulfillment_mode <> 'cumulative_contributions' OR e.liability_id IS NULL THEN RETURN; END IF;

  SELECT * INTO l FROM public.liabilities WHERE id=e.liability_id;
  IF NOT FOUND OR l.balance_model <> 'revolving_account' OR l.linked_account_id IS NULL THEN RETURN; END IF;

  DELETE FROM public.cash_flow_event_funding
  WHERE cash_flow_event_id=e.id AND allocation_source='auto_card_minimum';

  SELECT greatest(e.amount-coalesce(sum(amount),0),0) INTO v_remaining FROM public.cash_flow_event_funding WHERE cash_flow_event_id=e.id;
  FOR r IN
    SELECT t.*
    FROM public.transactions t
    JOIN public.accounts fa ON fa.id=t.from_account_id
    WHERE t.to_account_id=l.linked_account_id
      AND fa.account_type IN ('bank','cash')
      AND t.transaction_type IN ('transfer','debt_payment')
      AND t.transaction_date BETWEEN e.period_start AND e.period_end
    ORDER BY t.occurred_at,t.id
  LOOP
    EXIT WHEN v_remaining<=0;
    SELECT COALESCE(SUM(f.amount),0) INTO v_tx_used
    FROM public.cash_flow_event_funding f WHERE f.transaction_id=r.id;
    v_available:=GREATEST(r.amount-v_tx_used,0);
    v_alloc:=LEAST(v_available,v_remaining);
    IF v_alloc>0 THEN
      INSERT INTO public.cash_flow_event_funding(
        cash_flow_event_id,transaction_id,amount,relation_type,allocation_source
      ) VALUES(e.id,r.id,v_alloc,'payment','auto_card_minimum');
      v_remaining:=v_remaining-v_alloc;
    END IF;
  END LOOP;

  PERFORM public.refresh_cash_flow_event_status(e.id);
END
$function$;

-- Component: database/functions/reconcile_credit_card_minimum_from_old_transaction--4945a36f7d.sql
CREATE OR REPLACE FUNCTION public.reconcile_credit_card_minimum_from_old_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
  IF OLD.to_account_id IS NULL OR OLD.transaction_date IS NULL THEN
    RETURN OLD;
  END IF;

  FOR r IN
    SELECT e.id
    FROM public.cash_flow_events e
    JOIN public.liabilities l ON l.id=e.liability_id
    WHERE e.fulfillment_mode='cumulative_contributions'
      AND e.status<>'cancelled'
      AND l.balance_model='revolving_account'
      AND l.linked_account_id=OLD.to_account_id
      AND OLD.transaction_date BETWEEN e.period_start AND e.period_end
  LOOP
    PERFORM public.reconcile_credit_card_minimum(r.id);
  END LOOP;

  RETURN OLD;
END
$function$;

-- Component: database/functions/reconcile_credit_card_minimum_from_transaction--189bfba7de.sql
CREATE OR REPLACE FUNCTION public.reconcile_credit_card_minimum_from_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT e.id
    FROM public.cash_flow_events e
    JOIN public.liabilities l ON l.id=e.liability_id
    WHERE e.fulfillment_mode='cumulative_contributions'
      AND e.status<>'cancelled'
      AND l.balance_model='revolving_account'
      AND l.linked_account_id=NEW.to_account_id
      AND NEW.transaction_date BETWEEN e.period_start AND e.period_end
  LOOP
    PERFORM public.reconcile_credit_card_minimum(r.id);
  END LOOP;
  RETURN NEW;
END
$function$;

-- Component: database/functions/reconcile_payment_buffer_funding_from_transaction--2d2145772a.sql
CREATE OR REPLACE FUNCTION public.reconcile_payment_buffer_funding_from_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_payment_account_id bigint;
  v_from_type text;
  v_available numeric;
  v_alloc numeric;
  r record;
begin
  if new.liability_id is null or new.to_account_id is null or new.from_account_id is null then
    return new;
  end if;

  select l.payment_account_id
  into v_payment_account_id
  from public.liabilities l
  where l.id=new.liability_id;

  select a.account_type
  into v_from_type
  from public.accounts a
  where a.id=new.from_account_id;

  if v_payment_account_id is distinct from new.to_account_id
     or v_from_type not in ('bank','cash')
     or new.transaction_type<>'transfer' or NOT EXISTS(SELECT 1 FROM public.accounts a WHERE a.id=NEW.to_account_id AND a.account_type='payment_buffer') then
    return new;
  end if;

  delete from public.cash_flow_event_funding
  where transaction_id=new.id
    and allocation_source='auto_payment_buffer';

  select greatest(new.amount-coalesce(sum(f.amount),0),0)
  into v_available
  from public.cash_flow_event_funding f
  where f.transaction_id=new.id;

  if coalesce(v_available,0)<=0 then
    return new;
  end if;

  for r in
    select s.event_id,s.cash_still_required,e.event_date
    from public.cash_flow_event_state s
    join public.cash_flow_events e on e.id=s.event_id
    where e.liability_id=new.liability_id
      and e.event_type='debt_payment'
      and e.status<>'cancelled'
      and s.cash_still_required>0
    order by
      case when e.event_date<=new.transaction_date then 0 else 1 end,
      abs(e.event_date-new.transaction_date),
      e.event_date,
      e.id
  loop
    exit when v_available<=0;
    v_alloc:=least(v_available,r.cash_still_required);
    if v_alloc>0 then
      insert into public.cash_flow_event_funding(
        cash_flow_event_id,transaction_id,amount,relation_type,allocation_source
      ) values(
        r.event_id,new.id,v_alloc,'funding','auto_payment_buffer'
      );
      v_available:=v_available-v_alloc;
    end if;
  end loop;

  return new;
end
$function$;

-- Component: database/functions/refresh_cash_flow--24981a6d0a.sql
CREATE OR REPLACE FUNCTION public.refresh_cash_flow()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 PERFORM public.generate_cash_flow_events(public.finance_business_date(now()),(public.finance_business_date(now())+interval '3 months')::date);
 PERFORM public.refresh_event_security();
END $function$;

-- Component: database/functions/refresh_cash_flow_event_from_allocation--176c3ff941.sql
CREATE OR REPLACE FUNCTION public.refresh_cash_flow_event_from_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP IN ('UPDATE','DELETE') THEN
    PERFORM public.refresh_cash_flow_event_status(OLD.cash_flow_event_id);
  END IF;
  IF TG_OP IN ('INSERT','UPDATE') THEN
    PERFORM public.refresh_cash_flow_event_status(NEW.cash_flow_event_id);
  END IF;
  RETURN COALESCE(NEW,OLD);
END
$function$;

-- Component: database/functions/refresh_cash_flow_event_status--7a84b59058.sql
CREATE OR REPLACE FUNCTION public.refresh_cash_flow_event_status(p_event_id bigint)
 RETURNS cash_flow_events
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.cash_flow_events;s record;v_last timestamptz;
BEGIN
 SELECT * INTO v FROM public.cash_flow_events WHERE id=p_event_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF v.status='cancelled' THEN RETURN v; END IF;
 SELECT * INTO s FROM public.get_cash_flow_event_state_as_of(now()) WHERE event_id=p_event_id;
 IF v.event_type='income' THEN SELECT last_received_at INTO v_last FROM public.get_income_event_state_as_of(now()) WHERE event_id=p_event_id;
 ELSE SELECT max(t.occurred_at) INTO v_last FROM public.cash_flow_event_funding f JOIN public.transactions t ON t.id=f.transaction_id
 WHERE f.cash_flow_event_id=p_event_id AND f.relation_type='payment' AND t.occurred_at<=now(); END IF;
 UPDATE public.cash_flow_events SET status=s.derived_status,is_secured=(s.cash_still_required=0),security_amount=least(amount,s.cash_committed_amount),
 actual_amount=CASE WHEN s.paid_amount>0 THEN s.paid_amount ELSE NULL END,actual_date=public.finance_business_date(v_last)
 WHERE id=p_event_id RETURNING * INTO v;
 RETURN v;
END
$function$;

-- Component: database/functions/refresh_cash_flow_security--bef82af046.sql
CREATE OR REPLACE FUNCTION public.refresh_cash_flow_security(p_start date, p_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE r record;n int:=0;BEGIN FOR r IN SELECT id FROM public.cash_flow_events WHERE event_date BETWEEN p_start AND p_end AND status<>'cancelled' LOOP PERFORM public.refresh_cash_flow_event_status(r.id);n:=n+1;END LOOP;RETURN n;END $function$;

-- Component: database/functions/refresh_event_security--cb28073649.sql
CREATE OR REPLACE FUNCTION public.refresh_event_security()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE r record;BEGIN FOR r IN SELECT id FROM public.cash_flow_events WHERE status<>'cancelled' LOOP PERFORM public.refresh_cash_flow_event_status(r.id);END LOOP;END $function$;

-- Component: database/functions/refresh_snapshot_dependents--e774891266.sql
CREATE OR REPLACE FUNCTION public.refresh_snapshot_dependents()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
 IF TG_TABLE_NAME='account_balance_snapshots' THEN
  FOR r IN SELECT id FROM public.liabilities WHERE linked_account_id IN (CASE WHEN TG_OP<>'INSERT' THEN OLD.account_id END,CASE WHEN TG_OP<>'DELETE' THEN NEW.account_id END) LOOP PERFORM public.sync_liability_principal_cache(r.id);END LOOP;
 ELSE
  IF TG_OP<>'INSERT' THEN PERFORM public.sync_liability_principal_cache(OLD.liability_id); END IF;
  IF TG_OP<>'DELETE' THEN PERFORM public.sync_liability_principal_cache(NEW.liability_id); END IF;
 END IF;
 RETURN COALESCE(NEW,OLD);
END $function$;

-- Component: database/functions/refresh_transaction_dependents--3513c6b0a2.sql
CREATE OR REPLACE FUNCTION public.refresh_transaction_dependents()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
 IF TG_OP='UPDATE' AND NEW.occurred_at IS DISTINCT FROM OLD.occurred_at THEN
  FOR r IN SELECT DISTINCT liability_id FROM public.debt_payment_details WHERE transaction_id=NEW.id LOOP PERFORM public.rebuild_debt_payment_movements(r.liability_id); END LOOP;
 END IF;
 IF TG_OP='UPDATE' THEN
  FOR r IN SELECT DISTINCT cash_flow_event_id FROM public.cash_flow_event_funding WHERE transaction_id=NEW.id LOOP PERFORM public.refresh_cash_flow_event_status(r.cash_flow_event_id); END LOOP;
 END IF;
 RETURN COALESCE(NEW,OLD);
END $function$;

-- Component: database/functions/set_credit_card_minimum--613f21d5d7.sql
CREATE OR REPLACE FUNCTION public.set_credit_card_minimum(p_liability_id bigint, p_amount numeric, p_due_date date)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  l public.liabilities;
  v_period_start date;
  v_candidate date;
  v_prev_month date;
  v_last_day int;
  v_event_id bigint;
  v_source_key text;
BEGIN
 PERFORM pg_advisory_xact_lock(20260905,731);
  IF p_amount<=0 THEN RAISE EXCEPTION 'minimum payment must be > 0'; END IF;
  SELECT * INTO l FROM public.liabilities WHERE id=p_liability_id FOR UPDATE;
  IF NOT FOUND OR l.balance_model<>'revolving_account' THEN
    RAISE EXCEPTION 'liability % is not a revolving credit card',p_liability_id;
  END IF;
  IF l.minimum_payment_calculation_day IS NULL THEN
    RAISE EXCEPTION 'minimum_payment_calculation_day is not set for liability %',p_liability_id;
  END IF;

  v_last_day:=EXTRACT(DAY FROM (date_trunc('month',p_due_date)+interval '1 month - 1 day'))::int;
  v_candidate:=make_date(EXTRACT(YEAR FROM p_due_date)::int,EXTRACT(MONTH FROM p_due_date)::int,LEAST(l.minimum_payment_calculation_day,v_last_day));
  IF v_candidate>p_due_date THEN
    v_prev_month:=(date_trunc('month',p_due_date)-interval '1 month')::date;
    v_last_day:=EXTRACT(DAY FROM (date_trunc('month',v_prev_month)+interval '1 month - 1 day'))::int;
    v_period_start:=make_date(EXTRACT(YEAR FROM v_prev_month)::int,EXTRACT(MONTH FROM v_prev_month)::int,LEAST(l.minimum_payment_calculation_day,v_last_day));
  ELSE
    v_period_start:=v_candidate;
  END IF;

  v_source_key:='card_min:'||p_liability_id::text||':'||to_char(p_due_date,'YYYY-MM');

  INSERT INTO public.cash_flow_events(
    event_date,event_type,amount,description,account_id,liability_id,is_planned,is_secured,
    period_start,period_end,calculation_method,living_budget_exempt,status,source_type,source_key,fulfillment_mode
  ) VALUES(
    p_due_date,'debt_payment',p_amount,l.name||' — минимальный платёж',l.linked_account_id,l.id,true,false,
    v_period_start,p_due_date,'bank_calculated_minimum',true,'planned','card_minimum',v_source_key,'cumulative_contributions'
  )
  ON CONFLICT(source_key) WHERE source_key IS NOT NULL DO UPDATE SET
    event_date=EXCLUDED.event_date,amount=EXCLUDED.amount,description=EXCLUDED.description,
    account_id=EXCLUDED.account_id,liability_id=EXCLUDED.liability_id,period_start=EXCLUDED.period_start,
    period_end=EXCLUDED.period_end,calculation_method=EXCLUDED.calculation_method,living_budget_exempt=true,
    source_type='card_minimum',fulfillment_mode='cumulative_contributions'
  RETURNING id INTO v_event_id;

  UPDATE public.liabilities
  SET minimum_payment=p_amount,payment_day=EXTRACT(DAY FROM p_due_date)::smallint
  WHERE id=p_liability_id;

  PERFORM public.reconcile_credit_card_minimum(v_event_id);
  RETURN v_event_id;
END
$function$;

-- Component: database/functions/sync_cash_flow_sources--2ed9ef51b8.sql
CREATE OR REPLACE FUNCTION public.sync_cash_flow_sources()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_today date:=public.finance_business_date(now());v_from date;v_to date;
BEGIN
 SELECT least(v_today,coalesce(min(event_date),v_today)),
        greatest((v_today+interval '3 months')::date,coalesce(max(event_date),v_today))
 INTO v_from,v_to FROM public.cash_flow_events
 WHERE source_type IN ('rule','bank_schedule') AND status NOT IN ('executed','partially_executed','cancelled');
 PERFORM public.generate_cash_flow_events(v_from,v_to);
 RETURN NULL;
END $function$;

-- Component: database/functions/sync_debt_payment_movements--e4b6004cb5.sql
CREATE OR REPLACE FUNCTION public.sync_debt_payment_movements()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN
  DELETE FROM public.liability_movements WHERE debt_payment_detail_id=OLD.id;
  PERFORM public.rebuild_debt_payment_movements(OLD.liability_id);
 END IF;
 IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND NEW.liability_id IS DISTINCT FROM OLD.liability_id) THEN PERFORM public.rebuild_debt_payment_movements(NEW.liability_id); END IF;
 RETURN COALESCE(NEW,OLD);
END
$function$;

-- Component: database/functions/sync_liability_principal_cache--493f3f0c4a.sql
CREATE OR REPLACE FUNCTION public.sync_liability_principal_cache(p_liability_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_p numeric;
BEGIN SELECT principal_balance INTO v_p FROM public.get_liability_balance(p_liability_id,now()); IF v_p IS NOT NULL THEN UPDATE public.liabilities SET principal_current=v_p WHERE id=p_liability_id; END IF; END $function$;

-- Component: database/functions/sync_salary_transaction_to_event--845fb072a1.sql
CREATE OR REPLACE FUNCTION public.sync_salary_transaction_to_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_old_changed boolean:=false;v_new_changed boolean:=false;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') AND OLD.income_event_id IS NOT NULL THEN
  IF TG_OP='DELETE' OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at OR NEW.income_event_id IS DISTINCT FROM OLD.income_event_id THEN UPDATE public.cash_flow_events SET income_completed_at=NULL WHERE id=OLD.income_event_id;END IF;
  PERFORM public.refresh_cash_flow_event_status(OLD.income_event_id);
 END IF;
 IF TG_OP IN ('INSERT','UPDATE') AND NEW.income_event_id IS NOT NULL THEN PERFORM public.refresh_cash_flow_event_status(NEW.income_event_id); END IF;
 IF TG_OP='UPDATE' THEN
  v_old_changed:=NEW.amount IS DISTINCT FROM OLD.amount OR NEW.salary_period_start IS DISTINCT FROM OLD.salary_period_start OR NEW.salary_component IS DISTINCT FROM OLD.salary_component OR NEW.transaction_type IS DISTINCT FROM OLD.transaction_type;
  v_new_changed:=v_old_changed;
 ELSE v_old_changed:=TG_OP='DELETE';v_new_changed:=TG_OP='INSERT';END IF;
 IF v_old_changed AND OLD.salary_component IN ('advance','vacation') THEN PERFORM public.generate_cash_flow_events(OLD.salary_period_start,(OLD.salary_period_start+interval '2 months')::date);END IF;
 IF v_new_changed AND NEW.salary_component IN ('advance','vacation') THEN PERFORM public.generate_cash_flow_events(NEW.salary_period_start,(NEW.salary_period_start+interval '2 months')::date);END IF;
 RETURN COALESCE(NEW,OLD);
END
$function$;

-- Component: database/functions/trg_sync_liability_cache_from_movements--68942a8473.sql
CREATE OR REPLACE FUNCTION public.trg_sync_liability_cache_from_movements()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint;
BEGIN v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.liability_id ELSE NEW.liability_id END; PERFORM public.sync_liability_principal_cache(v_id); IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $function$;

-- Component: database/functions/trg_sync_revolving_liability_cache--da3ad9487b.sql
CREATE OR REPLACE FUNCTION public.trg_sync_revolving_liability_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
 FOR r IN SELECT DISTINCT l.id FROM public.liabilities l WHERE l.balance_model='revolving_account' AND (l.linked_account_id=COALESCE(NEW.from_account_id,OLD.from_account_id) OR l.linked_account_id=COALESCE(NEW.to_account_id,OLD.to_account_id) OR (TG_OP='UPDATE' AND (l.linked_account_id=OLD.from_account_id OR l.linked_account_id=OLD.to_account_id))) LOOP PERFORM public.sync_liability_principal_cache(r.id); END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$;

-- Component: database/functions/validate_cash_flow_allocation--7bc13b6030.sql
CREATE OR REPLACE FUNCTION public.validate_cash_flow_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tx_amount numeric;
  v_tx_used numeric;
  v_event_amount numeric;
  v_event_used numeric;
  v_cash_used numeric;
  v_tx_type text;
  v_from_id bigint;
  v_to_id bigint;
  v_from_type text;
  v_to_type text;
  v_event_type text;
  v_liability_id bigint;
  v_event_account_id bigint;
  v_balance_model text;
  v_payment_account_id bigint;
  v_linked_account_id bigint;
begin
  select t.amount,t.transaction_type,t.from_account_id,t.to_account_id,fa.account_type,ta.account_type
    into v_tx_amount,v_tx_type,v_from_id,v_to_id,v_from_type,v_to_type
  from public.transactions t
  left join public.accounts fa on fa.id=t.from_account_id
  left join public.accounts ta on ta.id=t.to_account_id
  where t.id=new.transaction_id;
  if v_tx_amount is null then raise exception 'transaction % not found',new.transaction_id; end if;

  select e.amount,e.event_type,e.liability_id,e.account_id
    into v_event_amount,v_event_type,v_liability_id,v_event_account_id
  from public.cash_flow_events e where e.id=new.cash_flow_event_id;
  if v_event_amount is null then raise exception 'cash flow event % not found',new.cash_flow_event_id; end if;

  if v_liability_id is not null then
    select l.balance_model,l.payment_account_id,l.linked_account_id
      into v_balance_model,v_payment_account_id,v_linked_account_id
    from public.liabilities l where l.id=v_liability_id;
  end if;

  select coalesce(sum(f.amount),0) into v_tx_used
  from public.cash_flow_event_funding f
  where f.transaction_id=new.transaction_id and f.id<>coalesce(new.id,-1);
  if v_tx_used+new.amount>v_tx_amount+0.005 then
    raise exception 'allocation exceeds transaction amount: used %, new %, transaction %',v_tx_used,new.amount,v_tx_amount;
  end if;

  select coalesce(sum(f.amount),0) into v_event_used
  from public.cash_flow_event_funding f
  where f.cash_flow_event_id=new.cash_flow_event_id
    and f.relation_type=new.relation_type
    and f.id<>coalesce(new.id,-1);
  if v_event_used+new.amount>v_event_amount+0.005 then
    raise exception '% allocation exceeds event amount: used %, new %, event %',new.relation_type,v_event_used,new.amount,v_event_amount;
  end if;

  if new.relation_type='funding' then
    if v_tx_type<>'transfer' or v_from_type not in ('bank','cash') or v_to_type<>'payment_buffer' then
      raise exception 'funding must be a transfer from bank/cash to a payment_buffer; transaction % is type %, from %, to %',new.transaction_id,v_tx_type,v_from_type,v_to_type;
    end if;
    if v_balance_model='installment' and v_payment_account_id is not null and v_to_id<>v_payment_account_id then
      raise exception 'funding for installment liability % must go to payment account %, got %',v_liability_id,v_payment_account_id,v_to_id;
    end if;
    if v_liability_id is null and v_event_account_id is not null and v_to_id<>v_event_account_id then
      raise exception 'funding for event % must go to event payment account %, got %',new.cash_flow_event_id,v_event_account_id,v_to_id;
    end if;
  elsif new.relation_type='payment' then
    if v_event_type='debt_payment' then
      if v_balance_model='installment' then
        if v_payment_account_id is null or v_from_id<>v_payment_account_id or v_to_id is not null or v_tx_type<>'debt_payment' then
          raise exception 'installment payment must be an actual debit from payment_buffer % to external payee; transaction % is type %, from %, to %',v_payment_account_id,new.transaction_id,v_tx_type,v_from_id,v_to_id;
        end if;
      elsif v_balance_model='revolving_account' then
        if v_tx_type<>'debt_payment' or v_from_type not in ('bank','cash') or v_to_id is distinct from v_linked_account_id then
          raise exception 'revolving payment must be debt_payment from bank/cash to linked account %',v_linked_account_id;
        end if;
      else
        raise exception 'unsupported liability model % for payment allocation',v_balance_model;
      end if;
    elsif v_event_type in ('expense','planned_expense') then
      if v_tx_type<>'expense' or v_from_type not in ('bank','cash','payment_buffer') or v_to_id is not null then
        raise exception 'expense payment must be an actual expense debit to external payee';
      end if;
    else
      raise exception 'payment allocations are not supported for event_type %',v_event_type;
    end if;
  end if;

  if v_from_type in ('bank','cash') then
    select coalesce(sum(f.amount),0) into v_cash_used
    from public.cash_flow_event_funding f
    join public.transactions t on t.id=f.transaction_id
    join public.accounts a on a.id=t.from_account_id
    where f.cash_flow_event_id=new.cash_flow_event_id
      and f.id<>coalesce(new.id,-1)
      and a.account_type in ('bank','cash');
    if v_cash_used+new.amount>v_event_amount+0.005 then
      raise exception 'cash committed to event exceeds event amount: committed %, new %, event %',v_cash_used,new.amount,v_event_amount;
    end if;
  end if;
  return new;
end
$function$;

-- Component: database/functions/validate_debt_payment_details--fc68f8438d.sql
CREATE OR REPLACE FUNCTION public.validate_debt_payment_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_amount numeric;
  v_type text;
  v_liability bigint;
BEGIN
  SELECT amount,transaction_type,liability_id
  INTO v_amount,v_type,v_liability
  FROM public.transactions
  WHERE id=NEW.transaction_id;

  IF v_amount IS NULL THEN
    RAISE EXCEPTION 'transaction % not found',NEW.transaction_id;
  END IF;
  IF v_type <> 'debt_payment' THEN
    RAISE EXCEPTION 'transaction % must be debt_payment to have debt_payment_details',NEW.transaction_id;
  END IF;
  IF v_liability IS NOT NULL AND v_liability <> NEW.liability_id THEN
    RAISE EXCEPTION 'transaction liability % does not match detail liability %',v_liability,NEW.liability_id;
  END IF;
  IF round(NEW.principal_amount + NEW.interest_amount + NEW.fee_amount,2) <> round(v_amount,2) THEN
    RAISE EXCEPTION 'debt payment decomposition % does not equal transaction amount %',
      NEW.principal_amount + NEW.interest_amount + NEW.fee_amount,v_amount;
  END IF;
  RETURN NEW;
END
$function$;

-- Component: database/functions/validate_grace_reserve--d63891a4f9.sql
CREATE OR REPLACE FUNCTION public.validate_grace_reserve()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l public.liabilities;v_draw numeric;v_repay numeric;
BEGIN
 IF NEW.reserve_effect='none' THEN RETURN NEW;END IF;
 SELECT * INTO l FROM public.liabilities WHERE id=NEW.reserve_liability_id;
 IF NOT FOUND OR l.balance_model<>'revolving_account' THEN RAISE EXCEPTION 'grace reserve requires a revolving liability';END IF;
 IF NEW.reserve_effect='grace_draw' AND NEW.reserve_due_date<NEW.transaction_date THEN RAISE EXCEPTION 'reserve due date precedes draw';END IF;
 IF NEW.reserve_effect='grace_draw' AND (NEW.transaction_type<>'transfer' OR NEW.from_account_id IS DISTINCT FROM l.linked_account_id OR NEW.to_account_id IS NULL) THEN RAISE EXCEPTION 'grace draw must be a transfer from its credit card';END IF;
 IF NEW.reserve_effect='grace_repay' AND (NEW.transaction_type<>'debt_payment' OR NEW.to_account_id IS DISTINCT FROM l.linked_account_id) THEN RAISE EXCEPTION 'grace repayment must repay its credit card';END IF;
 IF EXISTS(SELECT 1 FROM public.transactions t WHERE t.id<>NEW.id AND t.reserve_liability_id=NEW.reserve_liability_id AND t.reserve_cycle=NEW.reserve_cycle AND t.reserve_due_date<>NEW.reserve_due_date) THEN RAISE EXCEPTION 'all movements of one grace cycle require the same due date';END IF;
 RETURN NEW;
END $function$;

-- Component: database/functions/validate_grace_reserve_deferred--303d13b645.sql
CREATE OR REPLACE FUNCTION public.validate_grace_reserve_deferred()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF EXISTS(WITH r AS (SELECT reserve_liability_id,reserve_cycle,occurred_at,id,sum(CASE reserve_effect WHEN 'grace_draw' THEN amount ELSE -amount END) OVER(PARTITION BY reserve_liability_id,reserve_cycle ORDER BY occurred_at,id) outstanding FROM public.transactions WHERE reserve_effect<>'none') SELECT 1 FROM r WHERE outstanding<0) THEN RAISE EXCEPTION 'grace repayments exceed preceding draws';END IF;
 RETURN NULL;
END $function$;

-- Component: database/functions/validate_transaction_category_allocations_deferred--2a4024676f.sql
CREATE OR REPLACE FUNCTION public.validate_transaction_category_allocations_deferred()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
 SELECT * INTO r FROM public.finance_data_issues() LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'finance integrity: %, entity %, details %',r.code,r.entity_id,r.details USING ERRCODE='23514'; END IF;
 RETURN COALESCE(NEW,OLD);
END
$function$;

-- Component: database/schema/views/balance_snapshots.sql
CREATE VIEW public."balance_snapshots" WITH (security_invoker = true) AS
 SELECT id,
    account_id,
    balance_date,
    balance,
    notes,
    created_at,
    balance_as_of
   FROM account_balance_snapshots;

-- Component: database/schema/views/cash_flow_event_settlement_summary.sql
CREATE VIEW public."cash_flow_event_settlement_summary" WITH (security_invoker = true) AS
 SELECT e.id AS cash_flow_event_id,
    s.amount AS planned_amount,
    s.paid_amount,
    s.funded_amount,
    s.remaining_payment_amount,
    s.cash_still_required AS remaining_funding_amount
   FROM cash_flow_events e
     JOIN get_cash_flow_event_state_as_of(now()) s(event_id, event_date, event_type, amount, description, account_id, liability_id, status, paid_amount, funded_amount, cash_committed_amount, remaining_payment_amount, cash_still_required, derived_status) ON s.event_id = e.id;

-- Component: database/schema/views/cash_flow_event_state.sql
CREATE VIEW public."cash_flow_event_state" WITH (security_invoker = true) AS
 SELECT event_id,
    event_date,
    event_type,
    amount,
    description,
    account_id,
    liability_id,
    status,
    paid_amount,
    funded_amount,
    cash_committed_amount,
    remaining_payment_amount,
    cash_still_required,
    derived_status
   FROM get_cash_flow_event_state_as_of(now()) get_cash_flow_event_state_as_of(event_id, event_date, event_type, amount, description, account_id, liability_id, status, paid_amount, funded_amount, cash_committed_amount, remaining_payment_amount, cash_still_required, derived_status);

-- Component: database/schema/views/liability_current_balances.sql
CREATE VIEW public."liability_current_balances" WITH (security_invoker = true) AS
 SELECT l.id AS liability_id,
    l.name,
    l.liability_type,
    l.balance_model,
    b.principal_balance,
    b.accrued_interest,
    b.fees_due,
    b.total_debt,
    l.payment_account_id,
    l.linked_account_id
   FROM liabilities l
     LEFT JOIN LATERAL get_liability_balance(l.id, now()) b(principal_balance, accrued_interest, fees_due, total_debt) ON true;

